        /* For ZIP64 we write 8-byte sizes; for regular, 4-byte */
        /* Use ZIP64 if sizes exceed 0xFFFFFFFF */
        if (zip_comp_size >= 0xFFFFFFFF || zip_uncomp_size >= 0xFFFFFFFF) {
            /* ZIP64 data descriptor */
            uint64_t cs = zip_comp_size;
            uint64_t us = zip_uncomp_size;
            fwrite(&cs, 8, 1, out);
            fwrite(&us, 8, 1, out);
        } else {
            write_u32_le(out, (uint32_t)zip_comp_size);
            write_u32_le(out, (uint32_t)zip_uncomp_size);
