    write_u32_le(fp, (uint32_t)mtime);

    /* XFL - compression level indicator */
    unsigned char xfl = 0;
    if (level == 1) xfl = 4;        /* fastest */
    else if (level >= 9) xfl = 2;   /* best */
    write_u8(fp, xfl);

    /* OS = 3 (Unix) */
    write_u8(fp, 3);

    /* File name (null-terminated) */
    if (name && *name) {
        write_bytes(fp, name, strlen(name));
        write_u8(fp, 0);
    }

