    /* Also encode compression level in FLEVEL bits 6-7 */
    int flevel = 0;
    if (level <= 1) flevel = 0;
    else if (level <= 5) flevel = 1;
    else if (level <= 8) flevel = 2; /* default is level 6 */
    else flevel = 3;

    int fcheck = 0;
    int flg = (flevel << 6) | fcheck;
    /* Ensure cmf*256 + flg is multiple of 31 */
    int n = (cmf * 256 + flg) % 31;
    if (n != 0) flg += (31 - n);

    write_u8(fp, (unsigned char)cmf);
    write_u8(fp, (unsigned char)flg);
