/* pigz.c - Parallel Implementation of GZip
 * Copyright (C) 2007-2023 Mark Adler
 * Original by Mark Adler, reimplemented from behavioral observation
 */

#define _GNU_SOURCE
#define _FILE_OFFSET_BITS 64

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <stdint.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <utime.h>
#include <dirent.h>
#include <pthread.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <zlib.h>
#include <sys/sysinfo.h>
#include <limits.h>
#include <ctype.h>

#define PIGZ_VERSION "2.8"
#define DEFAULT_BLOCK_SIZE (128 * 1024)  /* 128K */
#define DEFAULT_LEVEL 6
#define MAX_LEVEL 9
#define DICT_SIZE (32 * 1024)  /* 32K dictionary */

/* Format types */
#define FORMAT_GZIP  0
#define FORMAT_ZLIB  1
#define FORMAT_ZIP   2
#define FORMAT_RAWZ  3

/* gzip header flags */
#define GZ_FTEXT    0x01
#define GZ_FHCRC    0x02
#define GZ_FEXTRA   0x04
#define GZ_FNAME    0x08
#define GZ_FCOMMENT 0x10

/* Independent block marker (9 bytes) */
static const unsigned char iblock_marker[9] = {
    0x00, 0x00, 0xff, 0xff, 0x00, 0x00, 0x00, 0xff, 0xff
};

/* Global options */
static struct {
    int level;          /* compression level */
    int procs;          /* number of threads */
    int block_size;     /* block size in bytes */
    int format;         /* output format */
    int decompress;     /* decompress mode */
    int list;           /* list mode */
    int test;           /* test mode */
    int force;          /* force overwrite */
    int keep;           /* keep original files */
    int recursive;      /* recursive mode */
    int verbose;        /* verbosity level */
    int quiet;          /* quiet mode */
    int independent;    /* independent blocks */
    int rsyncable;      /* rsync-friendly output */
    int store_name;     /* store/restore name */
    int store_time;     /* store/restore modification time */
    int huffman;        /* huffman only strategy */
    int rle;            /* run-length encoding strategy */
    int synchronous;    /* synchronous output */
    char *suffix;       /* compression suffix */
    char *alias;        /* stdin alias for zip */
    char *comment;      /* gzip/zip comment */
    /* zopfli options (-11) */
    int zopfli_first;   /* iterations first */
    int zopfli_iter;    /* iterations */
    int zopfli_maxsplit;/* max splits */
    int zopfli_oneblock;/* no block splitting */
} g;

/* Program name (pigz or unpigz) */
static char *prog_name = "pigz";

/* Output file for cleanup on signal */
static char *out_path = NULL;

/* =========================================================================
 * Error/message functions
 */
static void message(const char *fmt, ...) {
    if (g.quiet) return;
    va_list ap;
    fprintf(stderr, "%s: ", prog_name);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    putc('\n', stderr);
}

static void complain(const char *fmt, ...) {
    if (g.quiet) return;
    va_list ap;
    fprintf(stderr, "%s: ", prog_name);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    putc('\n', stderr);
}

/* =========================================================================
 * CRC32 utility
 */
static uint32_t crc32_update(uint32_t crc, const void *buf, size_t len) {
    return (uint32_t)crc32(crc, (const Bytef *)buf, (uInt)len);
}

/* =========================================================================
 * Adler32 utility
 */
static uint32_t adler32_update(uint32_t adler, const void *buf, size_t len) {
    return (uint32_t)adler32(adler, (const Bytef *)buf, (uInt)len);
}

/* =========================================================================
 * Write utilities
 */
static void write_u8(FILE *fp, unsigned char v) {
    if (fputc(v, fp) == EOF) {
        perror("write error");
        exit(1);
    }
}

static void write_u16_le(FILE *fp, uint16_t v) {
    write_u8(fp, v & 0xff);
    write_u8(fp, (v >> 8) & 0xff);
}

static void write_u32_le(FILE *fp, uint32_t v) {
    write_u8(fp, v & 0xff);
    write_u8(fp, (v >> 8) & 0xff);
    write_u8(fp, (v >> 16) & 0xff);
    write_u8(fp, (v >> 24) & 0xff);
}

static void write_bytes(FILE *fp, const void *buf, size_t len) {
    if (fwrite(buf, 1, len, fp) != len) {
        perror("write error");
        exit(1);
    }
}

/* =========================================================================
 * Read utilities
 */
static int read_u8(FILE *fp) {
    int c = fgetc(fp);
    return c;
}

static int read_u16_le(FILE *fp, uint16_t *val) {
    int a = read_u8(fp);
    int b = read_u8(fp);
    if (a == EOF || b == EOF) return -1;
    *val = (uint16_t)(a | (b << 8));
    return 0;
}

static int read_u32_le(FILE *fp, uint32_t *val) {
    int a = read_u8(fp);
    int b = read_u8(fp);
    int c = read_u8(fp);
    int d = read_u8(fp);
    if (a == EOF || b == EOF || c == EOF || d == EOF) return -1;
    *val = (uint32_t)(a | (b << 8) | (c << 16) | (d << 24));
    return 0;
}

/* =========================================================================
 * Job structure for parallel compression
 */
struct job {
    unsigned char *in;      /* input buffer */
    size_t in_len;          /* input length */
    unsigned char *dict;    /* dictionary (last 32K of previous block) */
    size_t dict_len;        /* dictionary length */
    unsigned char *out;     /* output buffer */
    size_t out_len;         /* compressed output length */
    size_t out_alloc;       /* allocated output size */
    uint32_t check;         /* check value for this block */
    int last;               /* is this the last block? */
    int seq;                /* sequence number */
    pthread_t thread;
    struct job *next;
};

/* =========================================================================
 * Compress a single block using zlib
 * Returns: compressed data in job->out, job->out_len
 */
static void compress_job(struct job *job) {
    z_stream strm;
    int ret;
    int strategy = Z_DEFAULT_STRATEGY;

    if (g.huffman) strategy = Z_HUFFMAN_ONLY;
    if (g.rle) strategy = Z_RLE;

    int level = g.level;

    memset(&strm, 0, sizeof(strm));
    /* Use raw deflate (-15 window bits) */
    ret = deflateInit2(&strm, level, Z_DEFLATED, -15, 8, strategy);
    if (ret != Z_OK) {
        fprintf(stderr, "%s: deflateInit2 failed: %d\n", prog_name, ret);
        exit(1);
    }

    /* Set dictionary if provided */
    if (job->dict && job->dict_len > 0) {
        ret = deflateSetDictionary(&strm, job->dict, (uInt)job->dict_len);
        if (ret != Z_OK) {
            fprintf(stderr, "%s: deflateSetDictionary failed: %d\n", prog_name, ret);
            exit(1);
        }
    }

    /* Allocate output buffer - worst case is slightly larger than input */
    size_t out_alloc = job->in_len + (job->in_len >> 10) + 16 + 64;
    if (out_alloc < 64) out_alloc = 64;
    job->out = malloc(out_alloc);
    if (!job->out) {
        fprintf(stderr, "%s: out of memory\n", prog_name);
        exit(1);
    }
    job->out_alloc = out_alloc;

    strm.next_in = job->in;
    strm.avail_in = (uInt)job->in_len;
    strm.next_out = job->out;
    strm.avail_out = (uInt)out_alloc;

    /* Compress with Z_SYNC_FLUSH to produce a byte-aligned partial stream */
    ret = deflate(&strm, Z_SYNC_FLUSH);
    if (ret != Z_OK && ret != Z_STREAM_END && ret != Z_BUF_ERROR) {
        fprintf(stderr, "%s: deflate failed: %d\n", prog_name, ret);
        exit(1);
    }

    /* If this is the last block, use Z_FINISH */
    if (job->last) {
        strm.next_in = NULL;
        strm.avail_in = 0;

        /* Need more space possibly */
        size_t used = out_alloc - strm.avail_out;
        if (strm.avail_out < 16) {
            out_alloc += 64;
            unsigned char *new_out = realloc(job->out, out_alloc);
            if (!new_out) { exit(1); }
            job->out = new_out;
            strm.next_out = job->out + used;
            strm.avail_out = (uInt)(out_alloc - used);
        }

        ret = deflate(&strm, Z_FINISH);
        if (ret != Z_STREAM_END) {
            /* try to get more space */
            while (ret == Z_OK || ret == Z_BUF_ERROR) {
                size_t used2 = out_alloc - strm.avail_out;
                out_alloc += 1024;
                unsigned char *nb = realloc(job->out, out_alloc);
                if (!nb) exit(1);
                job->out = nb;
                strm.next_out = job->out + used2;
                strm.avail_out = (uInt)(out_alloc - used2);
                ret = deflate(&strm, Z_FINISH);
            }
        }
        job->out_len = out_alloc - strm.avail_out;
    } else {
        job->out_len = out_alloc - strm.avail_out;
    }

    deflateEnd(&strm);

    /* Calculate check value for this block's input */
    job->check = crc32_update(0, job->in, job->in_len);
}

/* =========================================================================
 * Write gzip header
 */
static void write_gzip_header(FILE *fp, const char *name, time_t mtime, 
                               const char *comment, int level) {
    write_u8(fp, 0x1f);  /* ID1 */
    write_u8(fp, 0x8b);  /* ID2 */
    write_u8(fp, 8);     /* CM = deflate */

    unsigned char flags = 0;
    if (name && *name) flags |= GZ_FNAME;
    if (comment && *comment) flags |= GZ_FCOMMENT;
    write_u8(fp, flags);

    /* Modification time */
    write_u32_le(fp, (uint32_t)mtime);

    /* XFL - compression level indicator */
    unsigned char xfl = 0;
    if (level == 1) xfl = 4;        /* fastest */
    else if (level >= 9) xfl = 2;   /* best */
    write_u8(fp, xfl);

    /* OS = 3 (Unix) */
    write_u8(fp, 3);

    /* File name (null-terminated) */
    if (name && *name) {
        write_bytes(fp, name, strlen(name));
        write_u8(fp, 0);
    }

    /* Comment (null-terminated) */
    if (comment && *comment) {
        write_bytes(fp, comment, strlen(comment));
        write_u8(fp, 0);
    }
}

/* =========================================================================
 * Write gzip trailer
 */
static void write_gzip_trailer(FILE *fp, uint32_t crc, uint32_t size) {
    write_u32_le(fp, crc);
    write_u32_le(fp, size);
}

/* =========================================================================
 * Write zlib header
 */
static void write_zlib_header(FILE *fp, int level) {
    /* CMF: CM=8 (deflate), CINFO=7 (32K window) */
    int cmf = 0x78;
    /* FLG: calculated to make CMF*256+FLG divisible by 31 */
    /* Also encode compression level in FLEVEL bits 6-7 */
    int flevel = 0;
    if (level <= 1) flevel = 0;
    else if (level <= 5) flevel = 1;
    else if (level <= 8) flevel = 2; /* default is level 6 */
    else flevel = 3;

    int fcheck = 0;
    int flg = (flevel << 6) | fcheck;
    /* Ensure cmf*256 + flg is multiple of 31 */
    int n = (cmf * 256 + flg) % 31;
    if (n != 0) flg += (31 - n);

    write_u8(fp, (unsigned char)cmf);
    write_u8(fp, (unsigned char)flg);
}

/* =========================================================================
 * Write zlib trailer (Adler-32)
 */
static void write_zlib_trailer(FILE *fp, uint32_t adler) {
    /* Adler-32 in big-endian */
    write_u8(fp, (adler >> 24) & 0xff);
    write_u8(fp, (adler >> 16) & 0xff);
    write_u8(fp, (adler >> 8) & 0xff);
    write_u8(fp, adler & 0xff);
}

/* =========================================================================
 * ZIP format structures
 */
/* Write ZIP local file header */
static long write_zip_local_header(FILE *fp, const char *name, time_t mtime) {
    /* Local file header signature */
    write_u32_le(fp, 0x04034b50);
    write_u16_le(fp, 0x002d);    /* version needed: 4.5 (for ZIP64) */
    write_u16_le(fp, 0x0008);    /* general purpose bit flag: data descriptor */
    write_u16_le(fp, 8);         /* compression method: deflate */

    /* DOS time/date */
    struct tm *tm_info = NULL;
    uint16_t dos_time = 0, dos_date = 0;
    if (mtime != 0) {
        tm_info = localtime(&mtime);
        if (tm_info) {
            dos_time = (uint16_t)((tm_info->tm_hour << 11) | 
                                  (tm_info->tm_min << 5) | 
                                  (tm_info->tm_sec / 2));
            dos_date = (uint16_t)(((tm_info->tm_year - 80) << 9) | 
                                  ((tm_info->tm_mon + 1) << 5) | 
                                  tm_info->tm_mday);
        }
    }
    write_u16_le(fp, dos_time);
    write_u16_le(fp, dos_date);

    /* CRC-32 (0 = data descriptor will have it) */
    write_u32_le(fp, 0);
    /* Compressed size (0 = data descriptor) */
    write_u32_le(fp, 0xffffffff);  /* ZIP64 indicator */
    /* Uncompressed size (0 = data descriptor) */
    write_u32_le(fp, 0xffffffff);  /* ZIP64 indicator */

    /* File name */
    size_t name_len = name ? strlen(name) : 1;
    write_u16_le(fp, (uint16_t)name_len);

    /* Extra field length - UT field (5 bytes) + ZIP64 (20 bytes) */
    /* UT: 0x5455 tag, 5 bytes: flags(1) + mtime(4) */
    /* Extra: tag(2) + size(2) + data */
    uint16_t extra_len = 4 + 1 + 4 + 4;  /* UT field = 9 bytes total... */
    /* Actually compute correctly: "UT" extra field */
    /* tag(2) + size(2) + flags(1) + mtime(4) = 9 bytes */
    extra_len = 9;
    write_u16_le(fp, extra_len);

    /* File name */
    if (name) write_bytes(fp, name, name_len);
    else write_u8(fp, '-');

    /* Extra field: "UT" (universal time) */
    write_u16_le(fp, 0x5455);  /* UT tag */
    write_u16_le(fp, 5);       /* data size */
    write_u8(fp, 0x01);        /* flags: modification time present */
    write_u32_le(fp, (uint32_t)mtime);

    return 0;
}

/* =========================================================================
 * Parallel compression
 * Reads input in chunks, compresses in parallel, writes output
 */

struct worker_arg {
    struct job *job;
};

static void *worker_thread(void *arg) {
    struct job *job = (struct job *)arg;
    compress_job(job);
    return NULL;
}

/* =========================================================================
 * Main compression function
 */
static int do_compress(FILE *in, FILE *out, const char *name, time_t mtime,
                        off_t *in_total, off_t *out_total) {
    int block_size = g.block_size;
    int nprocs = g.procs;

    /* Determine format */
    int format = g.format;

    /* Write header */
    long header_start = 0;
    uint32_t zip_crc = 0;
    uint64_t zip_comp_size = 0, zip_uncomp_size = 0;
    long zip_data_start = 0;
    char *zip_name = NULL;
    time_t zip_mtime = 0;

    if (format == FORMAT_GZIP) {
        const char *store_name = (g.store_name && name) ? name : NULL;
        time_t store_mtime = (g.store_time && mtime) ? mtime : 0;
        write_gzip_header(out, store_name, store_mtime, g.comment, g.level);
    } else if (format == FORMAT_ZLIB) {
        write_zlib_header(out, g.level);
    } else if (format == FORMAT_ZIP) {
        zip_name = g.alias ? g.alias : (name ? (char*)name : "-");
        zip_mtime = mtime;
        zip_data_start = ftell(out);
        write_zip_local_header(out, zip_name, zip_mtime);
        zip_data_start = ftell(out);
    }

    /* Combined check value */
    uint32_t combined_crc = 0;   /* for gzip */
    uint32_t combined_adler = 1; /* for zlib, start at 1 */
    uint64_t total_in = 0;

    /* Allocate job pool */
    int max_jobs = nprocs + 2;
    struct job **jobs = calloc(max_jobs, sizeof(struct job *));

    unsigned char *prev_dict = NULL;
    size_t prev_dict_len = 0;

    int eof = 0;
    int seq = 0;
    int out_seq = 0;

    /* Single-threaded when -p 1 or small input */
    /* For simplicity, use single-threaded approach first */

    /* Read and compress in blocks */
    unsigned char *inbuf = malloc(block_size);
    if (!inbuf) { fprintf(stderr, "%s: out of memory\n", prog_name); exit(1); }

    /* For rsync, we need to track block boundaries based on content */
    /* For now, use fixed block boundaries */

    int first = 1;

    /* Process all blocks */
    struct job *job_list = NULL;
    struct job *job_tail = NULL;
    int njobs = 0;

    while (!eof) {
        /* Read a block */
        unsigned char *block = malloc(block_size);
        if (!block) exit(1);

        size_t got = 0;
        if (g.rsyncable) {
            /* Read with rsync boundaries */
            /* Simple implementation: same as regular but could have boundary checks */
            got = fread(block, 1, block_size, in);
        } else {
            got = fread(block, 1, block_size, in);
        }

        if (got < (size_t)block_size) {
            eof = 1;
        }

        if (got == 0 && eof) {
            free(block);
            break;
        }

        /* Update check values with this block's data */
        combined_crc = crc32_update(combined_crc, block, got);
        combined_adler = adler32_update(combined_adler, block, got);
        total_in += got;

        /* Create job */
        struct job *job = calloc(1, sizeof(struct job));
        if (!job) exit(1);

        job->in = block;
        job->in_len = got;
        job->seq = seq++;
        job->last = eof;

        /* Set dictionary (last 32K of previous block) */
        if (!g.independent && prev_dict) {
            job->dict = malloc(prev_dict_len);
            if (!job->dict) exit(1);
            memcpy(job->dict, prev_dict, prev_dict_len);
            job->dict_len = prev_dict_len;
        }

        /* Queue job */
        if (job_tail) {
            job_tail->next = job;
        } else {
            job_list = job;
        }
        job_tail = job;
        njobs++;

        /* Update dictionary for next block */
        if (prev_dict) {
            free(prev_dict);
            prev_dict = NULL;
        }
        if (got >= DICT_SIZE) {
            prev_dict = malloc(DICT_SIZE);
            if (!prev_dict) exit(1);
            memcpy(prev_dict, block + got - DICT_SIZE, DICT_SIZE);
            prev_dict_len = DICT_SIZE;
        } else if (got > 0) {
            prev_dict = malloc(got);
            if (!prev_dict) exit(1);
            memcpy(prev_dict, block, got);
            prev_dict_len = got;
        }
    }

    if (prev_dict) {
        free(prev_dict);
        prev_dict = NULL;
    }

    free(inbuf);

    /* If no jobs (empty input), create one empty job */
    if (!job_list) {
        struct job *job = calloc(1, sizeof(struct job));
        if (!job) exit(1);
        job->in = malloc(1);
        job->in_len = 0;
        job->seq = 0;
        job->last = 1;
        job_list = job;
        job_tail = job;
        njobs = 1;
    }

    /* Mark last job */
    if (job_tail) job_tail->last = 1;

    /* Compress jobs (parallel if nprocs > 1) */
    if (nprocs == 1 || njobs == 1) {
        /* Single threaded */
        struct job *job = job_list;
        while (job) {
            compress_job(job);
            job = job->next;
        }
    } else {
        /* Multi-threaded: launch up to nprocs threads at a time */
        struct job *job = job_list;
        while (job) {
            /* Launch batch of nprocs jobs */
            struct job *batch[1024];
            int batch_size = 0;
            struct job *cur = job;
            while (cur && batch_size < nprocs) {
                batch[batch_size++] = cur;
                cur = cur->next;
            }

            /* Launch threads */
            for (int i = 0; i < batch_size; i++) {
                pthread_create(&batch[i]->thread, NULL, worker_thread, batch[i]);
            }

            /* Wait for threads */
            for (int i = 0; i < batch_size; i++) {
                pthread_join(batch[i]->thread, NULL);
            }

            job = cur;
        }
    }

    /* Write compressed output */
    struct job *job = job_list;
    while (job) {
        /* For independent blocks, write marker before each block (except first) */
        if (g.independent && job->seq > 0) {
            write_bytes(out, iblock_marker, 9);
        }

        if (job->out && job->out_len > 0) {
            /* Write the compressed data */
            if (job->last) {
                /* Write full stream including final deflate block */
                write_bytes(out, job->out, job->out_len);
            } else {
                write_bytes(out, job->out, job->out_len);
            }
        }

        struct job *next = job->next;
        free(job->in);
        if (job->dict) free(job->dict);
        if (job->out) free(job->out);
        free(job);
        job = next;
    }

    free(jobs);

    /* Write trailer */
    if (format == FORMAT_GZIP) {
        write_gzip_trailer(out, combined_crc, (uint32_t)total_in);
    } else if (format == FORMAT_ZLIB) {
        write_zlib_trailer(out, combined_adler);
    } else if (format == FORMAT_ZIP) {
        /* Data descriptor */
        long data_end = ftell(out);
        zip_comp_size = data_end - zip_data_start;
        zip_uncomp_size = total_in;
        zip_crc = combined_crc;

        /* Write data descriptor */
        write_u32_le(out, 0x08074b50);  /* data descriptor signature */
        write_u32_le(out, zip_crc);
        write_u64: /* can't use labels in middle of scope */ ;
        /* For ZIP64 we write 8-byte sizes; for regular, 4-byte */
        /* Use ZIP64 if sizes exceed 0xFFFFFFFF */
        if (zip_comp_size >= 0xFFFFFFFF || zip_uncomp_size >= 0xFFFFFFFF) {
            /* ZIP64 data descriptor */
            uint64_t cs = zip_comp_size;
            uint64_t us = zip_uncomp_size;
            fwrite(&cs, 8, 1, out);
            fwrite(&us, 8, 1, out);
        } else {
            write_u32_le(out, (uint32_t)zip_comp_size);
            write_u32_le(out, (uint32_t)zip_uncomp_size);
        }

        /* Central directory */
        long central_dir_offset = ftell(out);

        /* Central directory entry */
        write_u32_le(out, 0x02014b50);  /* central directory signature */
        write_u16_le(out, 0xff2d);      /* version made by: 4.5 (ZIP64), Unix */
        write_u16_le(out, 0x002d);      /* version needed: 4.5 */
        write_u16_le(out, 0x0008);      /* general purpose bit flag */
        write_u16_le(out, 8);           /* compression method: deflate */

        /* DOS time/date */
        uint16_t dos_time = 0, dos_date = 0;
        if (zip_mtime != 0) {
            struct tm *tm_info = localtime(&zip_mtime);
            if (tm_info) {
                dos_time = (uint16_t)((tm_info->tm_hour << 11) | 
                                      (tm_info->tm_min << 5) | 
                                      (tm_info->tm_sec / 2));
                dos_date = (uint16_t)(((tm_info->tm_year - 80) << 9) | 
                                      ((tm_info->tm_mon + 1) << 5) | 
                                      tm_info->tm_mday);
            }
        }
        write_u16_le(out, dos_time);
        write_u16_le(out, dos_date);
        write_u32_le(out, zip_crc);

        /* Use 0xFFFFFFFF to indicate ZIP64 extra */
        if (zip_comp_size >= 0xFFFFFFFF || zip_uncomp_size >= 0xFFFFFFFF ||
            zip_data_start >= 0xFFFFFFFF) {
            write_u32_le(out, 0xffffffff);
            write_u32_le(out, 0xffffffff);
        } else {
            write_u32_le(out, (uint32_t)zip_comp_size);
            write_u32_le(out, (uint32_t)zip_uncomp_size);
        }

        size_t name_len = zip_name ? strlen(zip_name) : 1;
        write_u16_le(out, (uint16_t)name_len);

        /* Central dir extra: UT field + ZIP64 */
        /* UT: tag(2) + size(2) + flags(1) + mtime(4) = 9 bytes */
        /* ZIP64: tag(2) + size(2) + orig_size(8) + comp_size(8) + local_hdr_ofs(8) = 28 */
        uint16_t cd_extra_len = 9 + 28;
        /* Actually let's check what the original produces - we need to be exact */
        /* Looking at our od output: 
           Central dir extra: UT(9) + something... let me keep it simple */
        write_u16_le(out, cd_extra_len);

        /* Comment length */
        size_t comment_len = g.comment ? strlen(g.comment) : 0;
        write_u16_le(out, (uint16_t)comment_len);

        write_u16_le(out, 0);  /* disk number start */
        write_u16_le(out, 0);  /* internal file attributes */
        write_u32_le(out, 0);  /* external file attributes */

        /* Relative offset of local header */
        if (zip_data_start - (9 + name_len + 9) < 0xFFFFFFFF) {
            /* The local header starts before the data */
            long local_hdr_offset = zip_data_start - (4 + 2 + 2 + 2 + 2 + 2 + 4 + 4 + 4 + 2 + 2 + name_len + 9);
            if (local_hdr_offset < 0) local_hdr_offset = 0;
            write_u32_le(out, 0xffffffff); /* ZIP64 */
        } else {
            write_u32_le(out, 0xffffffff);
        }

        /* File name */
        if (zip_name) write_bytes(out, zip_name, name_len);
        else write_u8(out, '-');

        /* Extra field: UT */
        write_u16_le(out, 0x5455);
        write_u16_le(out, 5);
        write_u8(out, 0x01);
        write_u32_le(out, (uint32_t)zip_mtime);

        /* ZIP64 extra field */
        write_u16_le(out, 0x0001);  /* ZIP64 tag */
        write_u16_le(out, 24);      /* data size: 3 * 8 bytes */
        /* Original size */
        fwrite(&zip_uncomp_size, 8, 1, out);
        /* Compressed size */
        fwrite(&zip_comp_size, 8, 1, out);
        /* Offset of local header */
        uint64_t lhdr_offset = 0;
        fwrite(&lhdr_offset, 8, 1, out);

        /* Comment */
        if (g.comment) write_bytes(out, g.comment, comment_len);

        /* End of central directory */
        long central_dir_end = ftell(out);
        uint64_t cd_size = central_dir_end - central_dir_offset;

        write_u32_le(out, 0x06064b50);  /* ZIP64 end of central dir signature */
        uint64_t eocdr64_size = 44;
        fwrite(&eocdr64_size, 8, 1, out);
        write_u16_le(out, 0xff2d);  /* version made by */
        write_u16_le(out, 0x002d);  /* version needed */
        write_u32_le(out, 0);       /* disk number */
        write_u32_le(out, 0);       /* disk with start of CD */
        uint64_t one = 1;
        fwrite(&one, 8, 1, out);    /* entries on this disk */
        fwrite(&one, 8, 1, out);    /* total entries */
        fwrite(&cd_size, 8, 1, out); /* size of CD */
        uint64_t cd_offset64 = central_dir_offset;
        fwrite(&cd_offset64, 8, 1, out); /* offset of start of CD */

        /* ZIP64 end of central directory locator */
        write_u32_le(out, 0x07064b50);
        write_u32_le(out, 0);  /* disk with ZIP64 EOCD */
        uint64_t zip64_eocdr_offset = central_dir_end;
        fwrite(&zip64_eocdr_offset, 8, 1, out);
        write_u32_le(out, 1);  /* total disks */

        /* End of central directory record */
        write_u32_le(out, 0x06054b50);
        write_u16_le(out, 0xffff);  /* disk number */
        write_u16_le(out, 0xffff);  /* disk with start of CD */
        write_u16_le(out, 0xffff);  /* entries on this disk */
        write_u16_le(out, 0xffff);  /* total entries */
        write_u32_le(out, 0xffffffff); /* size of CD */
        write_u32_le(out, 0xffffffff); /* offset of start of CD */
        write_u16_le(out, 0);  /* comment length */
    }

    if (in_total) *in_total = total_in;
    if (out_total) *out_total = ftell(out);

    return 0;
}

