    if (g_level <= 1) flevel = 0;
    else if (g_level <= 5) flevel = 1;
    else if (g_level <= 8) flevel = 2;
    else flevel = 3;
    int flg = flevel << 6;
    int rem = (cmf * 256 + flg) % 31;
    if (rem) flg += (31 - rem);
    wbyte(fp, cmf);
    wbyte(fp, flg);
}

