    wbyte(fp, (adler >> 24) & 0xff);
    wbyte(fp, (adler >> 16) & 0xff);
    wbyte(fp, (adler >>  8) & 0xff);
    wbyte(fp, (adler      ) & 0xff);
}

/* DOS time conversion */
static void to_dos_time(time_t t, uint16_t *dtime, uint16_t *ddate) {
    *dtime = 0; *ddate = 0;
    if (!t) return;
    struct tm *tm = localtime(&t);
    if (!tm) return;
    *dtime = (uint16_t)((tm->tm_hour << 11) | (tm->tm_min << 5) | (tm->tm_sec / 2));
    *ddate = (uint16_t)(((tm->tm_year - 80) << 9) | ((tm->tm_mon + 1) << 5) | tm->tm_mday);
}

/* ZIP local file header */
static void write_zip_local(FILE *fp, const char *name, time_t mtime) {
    uint16_t dt, dd;
    to_dos_time(mtime, &dt, &dd);
    size_t nlen = name ? strlen(name) : 1;
    /* extra: ZIP64(20 bytes) + UT(9 bytes) = 29 */
    uint16_t extra_len = 4 + 16 + 4 + 5;  /* zip64 hdr(4)+data(16), UT hdr(4)+data(5) */

    wu32le(fp, 0x04034b50);     /* local sig */
    wu16le(fp, 45);             /* version needed: 4.5 */
    wu16le(fp, 0x0008);         /* flags: data descriptor */
    wu16le(fp, 8);              /* method: deflate */
    wu16le(fp, dt);
    wu16le(fp, dd);
    wu32le(fp, 0);              /* crc (in descriptor) */
    wu32le(fp, 0xffffffff);     /* comp size (ZIP64) */
    wu32le(fp, 0xffffffff);     /* uncomp size (ZIP64) */
    wu16le(fp, (uint16_t)nlen);
    wu16le(fp, extra_len);
    if (name) wbuf(fp, name, nlen);
    else wbyte(fp, '-');
    /* ZIP64 extra */
    wu16le(fp, 0x0001);
    wu16le(fp, 16);
    wu64le(fp, 0);   /* orig size unknown */
    wu64le(fp, 0);   /* comp size unknown */
    /* UT extra */
    wu16le(fp, 0x5455);
    wu16le(fp, 5);
    wbyte(fp, 0x01); /* mtime flag */
    wu32le(fp, (uint32_t)mtime);
}

/* ZIP data descriptor (ZIP64) */
static void write_zip_dd(FILE *fp, uint32_t crc, uint64_t comp, uint64_t uncomp) {
    wu32le(fp, 0x08074b50);
    wu32le(fp, crc);
    wu64le(fp, comp);
    wu64le(fp, uncomp);
}

/* ZIP central dir entry */
static void write_zip_cd(FILE *fp, const char *name, time_t mtime,
                          uint32_t crc, uint64_t comp, uint64_t uncomp,
                          uint64_t local_offset) {
    uint16_t dt, dd;
    to_dos_time(mtime, &dt, &dd);
    size_t nlen = name ? strlen(name) : 1;
    /* UT extra: 9 bytes */
    uint16_t extra_len = 9;

    wu32le(fp, 0x02014b50);     /* CD sig */
    wu16le(fp, 0xff2d);         /* version made by: 0xff=OS, 0x2d=45 */
    wu16le(fp, 45);             /* version needed */
    wu16le(fp, 0x0008);         /* flags */
    wu16le(fp, 8);              /* method */
    wu16le(fp, dt);
    wu16le(fp, dd);
    wu32le(fp, crc);
    wu32le(fp, (uint32_t)(comp  < 0xffffffff ? comp  : 0xffffffff));
    wu32le(fp, (uint32_t)(uncomp < 0xffffffff ? uncomp : 0xffffffff));
    wu16le(fp, (uint16_t)nlen);
    wu16le(fp, extra_len);
    wu16le(fp, 0);              /* comment len */
    wu16le(fp, 0);              /* disk start */
    wu16le(fp, 0);              /* int attribs */
    wu32le(fp, 0);              /* ext attribs */
    wu32le(fp, (uint32_t)(local_offset < 0xffffffff ? local_offset : 0xffffffff));
    if (name) wbuf(fp, name, nlen);
    else wbyte(fp, '-');
    /* UT extra */
    wu16le(fp, 0x5455);
    wu16le(fp, 5);
    wbyte(fp, 0x01);
    wu32le(fp, (uint32_t)mtime);
}

/* ZIP end of central dir */
static void write_zip_eocd(FILE *fp, uint64_t cd_offset, uint64_t cd_size) {
    wu32le(fp, 0x06054b50);
    wu16le(fp, 0);              /* disk */
    wu16le(fp, 0);              /* disk with start of CD */
    wu16le(fp, 1);              /* entries on this disk */
    wu16le(fp, 1);              /* total entries */
    wu32le(fp, (uint32_t)cd_size);
    wu32le(fp, (uint32_t)cd_offset);
    wu16le(fp, 0);              /* comment len */
}

/* ============================================================ */
/* Main compression routine */

static int compress_stream(FILE *in, FILE *out,
                            const char *name, time_t mtime,
                            uint64_t *in_size_out, uint64_t *out_size_out) {
    /* Write header */
    long zip_data_start = 0;
    char *zname = NULL;
    time_t zmtime = 0;

    if (g_format == FMT_GZIP) {
        write_gzip_hdr(fp: out, name: name, mtime: mtime);
    } else if (g_format == FMT_ZLIB) {
        write_zlib_hdr(out);
    } else {
        zname = g_alias ? g_alias : (name ? (char*)name : "-");
        zmtime = mtime;
        zip_data_start = ftell(out);
        write_zip_local(out, zname, zmtime);
        zip_data_start = ftell(out);
    }

    /* Accumulate check */
    uint32_t crc   = crc32(0, NULL, 0);
    uint32_t adler = adler32(0, NULL, 0);
    uint64_t total_in = 0;

    /* Read, compress, write */
    int nprocs = g_procs > 0 ? g_procs : get_nprocs();
    if (nprocs < 1) nprocs = 1;

    unsigned char *prev_dict = NULL;
    size_t prev_dict_len = 0;
    int seq = 0;
    int eof = 0;

    /* Build job list */
    struct job *head = NULL, *tail = NULL;

    while (!eof) {
        unsigned char *buf = malloc(g_block);
        if (!buf) bail("out of memory");
        size_t got = fread(buf, 1, g_block, in);
        if (got < (size_t)g_block) eof = 1;
        if (got == 0) { free(buf); break; }

        crc   = (uint32_t)crc32(crc,   buf, (uInt)got);
        adler = (uint32_t)adler32(adler, buf, (uInt)got);
        total_in += got;

        struct job *j = calloc(1, sizeof(*j));
        if (!j) bail("out of memory");
        j->in     = buf;
        j->in_len = got;
        j->seq    = seq++;
        j->last   = eof;

        if (!g_indep && prev_dict) {
            j->dict = malloc(prev_dict_len);
            if (!j->dict) bail("out of memory");
            memcpy(j->dict, prev_dict, prev_dict_len);
            j->dict_len = prev_dict_len;
        }

        if (tail) tail->next = j; else head = j;
        tail = j;

        /* Update dict */
        free(prev_dict); prev_dict = NULL;
        if (got >= DICT_SIZE) {
            prev_dict = malloc(DICT_SIZE);
            if (!prev_dict) bail("out of memory");
            memcpy(prev_dict, buf + got - DICT_SIZE, DICT_SIZE);
            prev_dict_len = DICT_SIZE;
        } else {
            prev_dict = malloc(got);
            if (!prev_dict) bail("out of memory");
            memcpy(prev_dict, buf, got);
            prev_dict_len = got;
        }
    }
    free(prev_dict);

    /* Handle empty input */
    if (!head) {
        struct job *j = calloc(1, sizeof(*j));
        if (!j) bail("out of memory");
        j->in = malloc(1); j->in_len = 0;
        j->seq = 0; j->last = 1;
        head = tail = j;
    }
    if (tail) tail->last = 1;

    /* Compress jobs */
    struct job *j;
    int cnt = 0;
    for (j = head; j; j = j->next) cnt++;

    if (nprocs == 1 || cnt == 1) {
        for (j = head; j; j = j->next) compress_block(j);
    } else {
        j = head;
        while (j) {
            struct job *batch[256];
            int n = 0;
            while (j && n < nprocs && n < 256) {
                batch[n++] = j;
                j = j->next;
            }
            for (int i = 0; i < n; i++)
                pthread_create(&batch[i]->tid, NULL, worker, batch[i]);
            for (int i = 0; i < n; i++)
                pthread_join(batch[i]->tid, NULL);
        }
    }

    /* Write compressed data */
    for (j = head; j; j = j->next) {
        if (g_indep && j->seq > 0)
            wbuf(out, ind_marker, 9);
        if (j->out && j->out_len)
            wbuf(out, j->out, j->out_len);
    }

    /* Free jobs */
    for (j = head; j; ) {
        struct job *nx = j->next;
        free(j->in);
        free(j->dict);
        free(j->out);
        free(j);
        j = nx;
    }

    /* Write trailer */
    long out_end = ftell(out);
    uint64_t comp_size = 0;

    if (g_format == FMT_GZIP) {
        write_gzip_trail(out, crc, total_in);
    } else if (g_format == FMT_ZLIB) {
        write_zlib_trail(out, adler);
    } else {
        /* ZIP */
        long data_end = ftell(out);
        comp_size = (uint64_t)(data_end - zip_data_start);
        write_zip_dd(out, crc, comp_size, total_in);
        long cd_start = ftell(out);
        write_zip_cd(out, zname, zmtime, crc, comp_size, total_in, 0);
        long cd_end = ftell(out);
        uint64_t cd_size = (uint64_t)(cd_end - cd_start);
        write_zip_eocd(out, (uint64_t)cd_start, cd_size);
    }

    if (in_size_out)  *in_size_out  = total_in;
    if (out_size_out) *out_size_out = (uint64_t)ftell(out);
    return 0;
}

