static void write_zip_eocd(FILE *fp, uint64_t cd_offset, uint64_t cd_size) {
    wu32le(fp, 0x06054b50);
    wu16le(fp, 0);              /* disk */
    wu16le(fp, 0);              /* disk with start of CD */
    wu16le(fp, 1);              /* entries on this disk */
    wu16le(fp, 1);              /* total entries */
    wu32le(fp, (uint32_t)cd_size);
    wu32le(fp, (uint32_t)cd_offset);
    wu16le(fp, 0);              /* comment len */
}

/* ============================================================ */
/* Main compression routine */

static int compress_stream(FILE *in, FILE *out,
                            const char *name, time_t mtime,
                            uint64_t *in_size_out, uint64_t *out_size_out) {
    /* Write header */
    long zip_data_start = 0;
    char *zname = NULL;
    time_t zmtime = 0;

    if (g_format == FMT_GZIP) {
        write_gzip_hdr(fp: out, name: name, mtime: mtime);
    } else if (g_format == FMT_ZLIB) {
        write_zlib_hdr(out);
    } else {
        zname = g_alias ? g_alias : (name ? (char*)name : "-");
        zmtime = mtime;
        zip_data_start = ftell(out);
        write_zip_local(out, zname, zmtime);
        zip_data_start = ftell(out);
    }

    /* Accumulate check */
    uint32_t crc   = crc32(0, NULL, 0);
    uint32_t adler = adler32(0, NULL, 0);
    uint64_t total_in = 0;

    /* Read, compress, write */
    int nprocs = g_procs > 0 ? g_procs : get_nprocs();
    if (nprocs < 1) nprocs = 1;

    unsigned char *prev_dict = NULL;
    size_t prev_dict_len = 0;
    int seq = 0;
    int eof = 0;

    /* Build job list */
    struct job *head = NULL, *tail = NULL;

    while (!eof) {
        unsigned char *buf = malloc(g_block);
        if (!buf) bail("out of memory");
        size_t got = fread(buf, 1, g_block, in);
        if (got < (size_t)g_block) eof = 1;
        if (got == 0) { free(buf); break; }

        crc   = (uint32_t)crc32(crc,   buf, (uInt)got);
        adler = (uint32_t)adler32(adler, buf, (uInt)got);
        total_in += got;

        struct job *j = calloc(1, sizeof(*j));
        if (!j) bail("out of memory");
        j->in     = buf;
        j->in_len = got;
        j->seq    = seq++;
        j->last   = eof;

        if (!g_indep && prev_dict) {
            j->dict = malloc(prev_dict_len);
            if (!j->dict) bail("out of memory");
            memcpy(j->dict, prev_dict, prev_dict_len);
            j->dict_len = prev_dict_len;
        }

        if (tail) tail->next = j; else head = j;
        tail = j;

        /* Update dict */
        free(prev_dict); prev_dict = NULL;
        if (got >= DICT_SIZE) {
            prev_dict = malloc(DICT_SIZE);
            if (!prev_dict) bail("out of memory");
            memcpy(prev_dict, buf + got - DICT_SIZE, DICT_SIZE);
            prev_dict_len = DICT_SIZE;
        } else {
            prev_dict = malloc(got);
            if (!prev_dict) bail("out of memory");
            memcpy(prev_dict, buf, got);
            prev_dict_len = got;
        }
    }
    free(prev_dict);

    /* Handle empty input */
    if (!head) {
        struct job *j = calloc(1, sizeof(*j));
        if (!j) bail("out of memory");
        j->in = malloc(1); j->in_len = 0;
        j->seq = 0; j->last = 1;
        head = tail = j;
    }
    if (tail) tail->last = 1;

    /* Compress jobs */
    struct job *j;
    int cnt = 0;
    for (j = head; j; j = j->next) cnt++;

    if (nprocs == 1 || cnt == 1) {
        for (j = head; j; j = j->next) compress_block(j);
    } else {
        j = head;
        while (j) {
            struct job *batch[256];
            int n = 0;
            while (j && n < nprocs && n < 256) {
                batch[n++] = j;
                j = j->next;
            }
            for (int i = 0; i < n; i++)
                pthread_create(&batch[i]->tid, NULL, worker, batch[i]);
            for (int i = 0; i < n; i++)
                pthread_join(batch[i]->tid, NULL);
        }
    }

    /* Write compressed data */
    for (j = head; j; j = j->next) {
        if (g_indep && j->seq > 0)
            wbuf(out, ind_marker, 9);
        if (j->out && j->out_len)
            wbuf(out, j->out, j->out_len);
    }

    /* Free jobs */
    for (j = head; j; ) {
        struct job *nx = j->next;
        free(j->in);
        free(j->dict);
        free(j->out);
        free(j);
        j = nx;
    }

    /* Write trailer */
    long out_end = ftell(out);
    uint64_t comp_size = 0;

    if (g_format == FMT_GZIP) {
        write_gzip_trail(out, crc, total_in);
    } else if (g_format == FMT_ZLIB) {
        write_zlib_trail(out, adler);
    } else {
        /* ZIP */
        long data_end = ftell(out);
        comp_size = (uint64_t)(data_end - zip_data_start);
        write_zip_dd(out, crc, comp_size, total_in);
        long cd_start = ftell(out);
        write_zip_cd(out, zname, zmtime, crc, comp_size, total_in, 0);
        long cd_end = ftell(out);
        uint64_t cd_size = (uint64_t)(cd_end - cd_start);
        write_zip_eocd(out, (uint64_t)cd_start, cd_size);
    }

    if (in_size_out)  *in_size_out  = total_in;
    if (out_size_out) *out_size_out = (uint64_t)ftell(out);
    return 0;
}

