/* pigz.c -- parallel implementation of gzip
 * Reimplemented from behavioral observation of pigz 2.8
 * Original by Mark Adler
 */

#define _GNU_SOURCE
#define _FILE_OFFSET_BITS 64

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <stdint.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <utime.h>
#include <dirent.h>
#include <pthread.h>
#include <time.h>
#include <signal.h>
#include <zlib.h>
#include <sys/sysinfo.h>
#include <ctype.h>

#define PIGZ_VERSION "2.8"
#define DEFAULT_BLOCK (128 * 1024)
#define DEFAULT_LEVEL 6
#define DICT_SIZE (32 * 1024)

/* Format */
#define FMT_GZIP 0
#define FMT_ZLIB 1
#define FMT_ZIP  2

/* gzip flags */
#define GZFTEXT    0x01
#define GZFHCRC    0x02
#define GZFEXTRA   0x04
#define GZFNAME    0x08
#define GZFCOMMENT 0x10

static const unsigned char ind_marker[9] = {
    0x00, 0x00, 0xff, 0xff, 0x00, 0x00, 0x00, 0xff, 0xff
};

/* Global options */
static int g_level = DEFAULT_LEVEL;
static int g_procs = 0;        /* 0 = auto */
static int g_block = DEFAULT_BLOCK;
static int g_format = FMT_GZIP;
static int g_decomp = 0;
static int g_list = 0;
static int g_test = 0;
static int g_force = 0;
static int g_keep = 0;
static int g_recur = 0;
static int g_verbose = 0;
static int g_quiet = 0;
static int g_indep = 0;
static int g_rsync = 0;
static int g_name = 1;         /* store name by default */
static int g_mtime = 1;        /* store mtime by default */
static int g_huffman = 0;
static int g_rle = 0;
static int g_sync = 0;
static char *g_suffix = NULL;
static char *g_alias = NULL;
static char *g_comment = NULL;
/* -11 zopfli options (not implemented, just accepted) */
static int g_zopfli_first = 0;
static int g_zopfli_iter = 15;
static int g_zopfli_maxsplit = 15;
static int g_zopfli_oneblock = 0;

static char *prog = "pigz";
static int g_ret = 0;  /* return value */

/* ============================================================ */
/* Utility */

static void bail(const char *fmt, ...) {
    if (!g_quiet) {
        va_list ap;
        fprintf(stderr, "%s: ", prog);
        va_start(ap, fmt);
        vfprintf(stderr, fmt, ap);
        va_end(ap);
        fputc('\n', stderr);
    }
    exit(1);
}

static void warn(const char *fmt, ...) {
    if (!g_quiet) {
        va_list ap;
        fprintf(stderr, "%s: ", prog);
        va_start(ap, fmt);
        vfprintf(stderr, fmt, ap);
        va_end(ap);
        fputc('\n', stderr);
    }
    g_ret = 1;
}

static void say(const char *fmt, ...) {
    if (g_quiet) return;
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
}

/* ============================================================ */
/* Write helpers */

static void wbyte(FILE *fp, unsigned v) {
    if (fputc(v & 0xff, fp) == EOF) bail("write error: %s", strerror(errno));
}

static void wu16le(FILE *fp, unsigned v) {
    wbyte(fp, v);
    wbyte(fp, v >> 8);
}

static void wu32le(FILE *fp, uint32_t v) {
    wbyte(fp, v);
    wbyte(fp, v >> 8);
    wbyte(fp, v >> 16);
    wbyte(fp, v >> 24);
}

static void wu64le(FILE *fp, uint64_t v) {
    wu32le(fp, (uint32_t)v);
    wu32le(fp, (uint32_t)(v >> 32));
}

static void wbuf(FILE *fp, const void *buf, size_t len) {
    if (len && fwrite(buf, 1, len, fp) != len)
        bail("write error: %s", strerror(errno));
}

/* ============================================================ */
/* Read helpers */

static int rbyte(FILE *fp) { return fgetc(fp); }

static int ru16le(FILE *fp, uint16_t *v) {
    int a = rbyte(fp), b = rbyte(fp);
    if (a == EOF || b == EOF) return -1;
    *v = (uint16_t)(a | (b << 8));
    return 0;
}

static int ru32le(FILE *fp, uint32_t *v) {
    int a = rbyte(fp), b = rbyte(fp), c = rbyte(fp), d = rbyte(fp);
    if (a == EOF || b == EOF || c == EOF || d == EOF) return -1;
    *v = (uint32_t)(a | (b<<8) | (c<<16) | (d<<24));
    return 0;
}

static int ru64le(FILE *fp, uint64_t *v) {
    uint32_t lo, hi;
    if (ru32le(fp, &lo) || ru32le(fp, &hi)) return -1;
    *v = lo | ((uint64_t)hi << 32);
    return 0;
}

/* ============================================================ */
/* Parallel compression job */

struct job {
    int seq;
    int last;
    unsigned char *in;
    size_t in_len;
    unsigned char *dict;
    size_t dict_len;
    unsigned char *out;
    size_t out_len;
    pthread_t tid;
    struct job *next;
};

static void compress_block(struct job *j) {
    int strategy = Z_DEFAULT_STRATEGY;
    if (g_huffman) strategy = Z_HUFFMAN_ONLY;
    if (g_rle)     strategy = Z_RLE;

    z_stream s;
    memset(&s, 0, sizeof(s));
    if (deflateInit2(&s, g_level, Z_DEFLATED, -15, 8, strategy) != Z_OK)
        bail("deflateInit2 failed");

    if (j->dict && j->dict_len)
        deflateSetDictionary(&s, j->dict, (uInt)j->dict_len);

    size_t oa = j->in_len + (j->in_len >> 10) + 128;
    if (oa < 128) oa = 128;
    j->out = malloc(oa);
    if (!j->out) bail("out of memory");

    s.next_in  = j->in;
    s.avail_in = (uInt)j->in_len;
    s.next_out = j->out;
    s.avail_out = (uInt)oa;

    int flush = j->last ? Z_FINISH : Z_SYNC_FLUSH;
    int r;
    for (;;) {
        r = deflate(&s, flush);
        if (r == Z_STREAM_END || r == Z_OK || r == Z_BUF_ERROR) {
            if (s.avail_out > 0 && r != Z_BUF_ERROR) break;
            /* need more output space */
            size_t used = oa - s.avail_out;
            oa += oa / 2 + 64;
            j->out = realloc(j->out, oa);
            if (!j->out) bail("out of memory");
            s.next_out  = j->out + used;
            s.avail_out = (uInt)(oa - used);
        } else {
            bail("deflate failed: %d", r);
        }
        if (r == Z_STREAM_END) break;
    }
    j->out_len = oa - s.avail_out;
    deflateEnd(&s);
}

static void *worker(void *arg) {
    compress_block((struct job *)arg);
    return NULL;
}

/* ============================================================ */
/* gzip header/trailer */

static void write_gzip_hdr(FILE *fp, const char *name, time_t mtime) {
    wbyte(fp, 0x1f);
    wbyte(fp, 0x8b);
    wbyte(fp, 8);           /* CM */
    unsigned char flg = 0;
    if (g_name && name && *name) flg |= GZFNAME;
    if (g_comment && *g_comment) flg |= GZFCOMMENT;
    wbyte(fp, flg);
    wu32le(fp, (uint32_t)(g_mtime ? mtime : 0));
    /* XFL */
    unsigned char xfl = 0;
    if (g_level <= 1) xfl = 4;
    else if (g_level >= 9) xfl = 2;
    wbyte(fp, xfl);
    wbyte(fp, 3);           /* OS = Unix */
    if (flg & GZFNAME) {
        wbuf(fp, name, strlen(name));
        wbyte(fp, 0);
    }
    if (flg & GZFCOMMENT) {
        wbuf(fp, g_comment, strlen(g_comment));
        wbyte(fp, 0);
    }
}

static void write_gzip_trail(FILE *fp, uint32_t crc, uint64_t len) {
    wu32le(fp, crc);
    wu32le(fp, (uint32_t)len);
}

/* zlib header */
static void write_zlib_hdr(FILE *fp) {
    int cmf = 0x78;
    int flevel = 0;
    if (g_level <= 1) flevel = 0;
    else if (g_level <= 5) flevel = 1;
    else if (g_level <= 8) flevel = 2;
    else flevel = 3;
    int flg = flevel << 6;
    int rem = (cmf * 256 + flg) % 31;
    if (rem) flg += (31 - rem);
    wbyte(fp, cmf);
    wbyte(fp, flg);
}

static void write_zlib_trail(FILE *fp, uint32_t adler) {
    wbyte(fp, (adler >> 24) & 0xff);
    wbyte(fp, (adler >> 16) & 0xff);
    wbyte(fp, (adler >>  8) & 0xff);
    wbyte(fp, (adler      ) & 0xff);
}

/* DOS time conversion */
static void to_dos_time(time_t t, uint16_t *dtime, uint16_t *ddate) {
    *dtime = 0; *ddate = 0;
    if (!t) return;
    struct tm *tm = localtime(&t);
    if (!tm) return;
    *dtime = (uint16_t)((tm->tm_hour << 11) | (tm->tm_min << 5) | (tm->tm_sec / 2));
    *ddate = (uint16_t)(((tm->tm_year - 80) << 9) | ((tm->tm_mon + 1) << 5) | tm->tm_mday);
}

/* ZIP local file header */
static void write_zip_local(FILE *fp, const char *name, time_t mtime) {
    uint16_t dt, dd;
    to_dos_time(mtime, &dt, &dd);
    size_t nlen = name ? strlen(name) : 1;
    /* extra: ZIP64(20 bytes) + UT(9 bytes) = 29 */
    uint16_t extra_len = 4 + 16 + 4 + 5;  /* zip64 hdr(4)+data(16), UT hdr(4)+data(5) */

    wu32le(fp, 0x04034b50);     /* local sig */
    wu16le(fp, 45);             /* version needed: 4.5 */
    wu16le(fp, 0x0008);         /* flags: data descriptor */
    wu16le(fp, 8);              /* method: deflate */
    wu16le(fp, dt);
    wu16le(fp, dd);
    wu32le(fp, 0);              /* crc (in descriptor) */
    wu32le(fp, 0xffffffff);     /* comp size (ZIP64) */
    wu32le(fp, 0xffffffff);     /* uncomp size (ZIP64) */
    wu16le(fp, (uint16_t)nlen);
    wu16le(fp, extra_len);
    if (name) wbuf(fp, name, nlen);
    else wbyte(fp, '-');
    /* ZIP64 extra */
    wu16le(fp, 0x0001);
    wu16le(fp, 16);
    wu64le(fp, 0);   /* orig size unknown */
    wu64le(fp, 0);   /* comp size unknown */
    /* UT extra */
    wu16le(fp, 0x5455);
    wu16le(fp, 5);
    wbyte(fp, 0x01); /* mtime flag */
    wu32le(fp, (uint32_t)mtime);
}

/* ZIP data descriptor (ZIP64) */
static void write_zip_dd(FILE *fp, uint32_t crc, uint64_t comp, uint64_t uncomp) {
    wu32le(fp, 0x08074b50);
    wu32le(fp, crc);
    wu64le(fp, comp);
    wu64le(fp, uncomp);
}

/* ZIP central dir entry */
static void write_zip_cd(FILE *fp, const char *name, time_t mtime,
                          uint32_t crc, uint64_t comp, uint64_t uncomp,
                          uint64_t local_offset) {
    uint16_t dt, dd;
    to_dos_time(mtime, &dt, &dd);
    size_t nlen = name ? strlen(name) : 1;
    /* UT extra: 9 bytes */
    uint16_t extra_len = 9;

    wu32le(fp, 0x02014b50);     /* CD sig */
    wu16le(fp, 0xff2d);         /* version made by: 0xff=OS, 0x2d=45 */
    wu16le(fp, 45);             /* version needed */
    wu16le(fp, 0x0008);         /* flags */
    wu16le(fp, 8);              /* method */
    wu16le(fp, dt);
    wu16le(fp, dd);
    wu32le(fp, crc);
    wu32le(fp, (uint32_t)(comp  < 0xffffffff ? comp  : 0xffffffff));
    wu32le(fp, (uint32_t)(uncomp < 0xffffffff ? uncomp : 0xffffffff));
    wu16le(fp, (uint16_t)nlen);
    wu16le(fp, extra_len);
    wu16le(fp, 0);              /* comment len */
    wu16le(fp, 0);              /* disk start */
    wu16le(fp, 0);              /* int attribs */
    wu32le(fp, 0);              /* ext attribs */
    wu32le(fp, (uint32_t)(local_offset < 0xffffffff ? local_offset : 0xffffffff));
    if (name) wbuf(fp, name, nlen);
    else wbyte(fp, '-');
    /* UT extra */
    wu16le(fp, 0x5455);
    wu16le(fp, 5);
    wbyte(fp, 0x01);
    wu32le(fp, (uint32_t)mtime);
}

/* ZIP end of central dir */
static void write_zip_eocd(FILE *fp, uint64_t cd_offset, uint64_t cd_size) {
    wu32le(fp, 0x06054b50);
    wu16le(fp, 0);              /* disk */
    wu16le(fp, 0);              /* disk with start of CD */
    wu16le(fp, 1);              /* entries on this disk */
    wu16le(fp, 1);              /* total entries */
    wu32le(fp, (uint32_t)cd_size);
    wu32le(fp, (uint32_t)cd_offset);
    wu16le(fp, 0);              /* comment len */
}

/* ============================================================ */
/* Main compression routine */

static int compress_stream(FILE *in, FILE *out,
                            const char *name, time_t mtime,
                            uint64_t *in_size_out, uint64_t *out_size_out) {
    /* Write header */
