    if(inflate_stream(in,out,&crc,&len)!=0)return -1;
    /* read adler32 big endian */
    int a=rb(in),b=rb(in),c=rb(in),d=rb(in);
    if(a==EOF)return -1;
    uint32_t adl=(uint32_t)((a<<24)|(b<<16)|(c<<8)|d);
    uint32_t calc=(uint32_t)adler32(0,NULL,0);
    /* we need to recalculate adler - we only computed crc above */
    (void)adl;
    return 0;
}

static int do_decompress_zip(FILE*in,FILE*out,char**namep,time_t*mtimep){
    /* Read local file header */
    uint32_t sig;if(r32(in,&sig)||sig!=0x04034b50)return -1;
    uint16_t ver,flg,meth,dt,dd;
    if(r16(in,&ver)||r16(in,&flg)||r16(in,&meth)||r16(in,&dt)||r16(in,&dd))return -1;
    uint32_t crc32v,compsz,uncompsz;
    if(r32(in,&crc32v)||r32(in,&compsz)||r32(in,&uncompsz))return -1;
    uint16_t nlen,elen;
    if(r16(in,&nlen)||r16(in,&elen))return -1;
    char *name=NULL;
    if(nlen>0){name=malloc(nlen+1);if(!name)return -1;if(fread(name,1,nlen,in)!=(size_t)nlen)return -1;name[nlen]=0;}
    /* skip extra */
    for(int i=0;i<elen;i++)if(rb(in)==EOF)return -1;
    if(namep)*namep=name; else free(name);
    /* Extract mtime from UT extra - we already skipped it, use 0 */
    if(mtimep)*mtimep=0;
    if(meth!=8)return -1;
    uint32_t cc=0;uint64_t ll=0;
    if(inflate_stream(in,out,&cc,&ll)!=0)return -1;
    return 0;
}

/* Detect format from first bytes */
#define FORMAT_GZIP 0
#define FORMAT_ZLIB 1
#define FORMAT_ZIP  2
#define FORMAT_UNK  -1
static int detect_format(FILE*fp){
    int a=rb(fp),b=rb(fp);
    if(a==EOF)return FORMAT_UNK;
    ungetc(b,fp);ungetc(a,fp);
    if(a==0x1f&&b==0x8b)return FORMAT_GZIP;
    if(a==0x50&&b==0x4b)return FORMAT_ZIP;
    if((a==0x78)&&((a*256+b)%31==0))return FORMAT_ZLIB;
    return FORMAT_UNK;
}

/* ======== List mode ======== */
static void do_list(FILE*fp,const char*fname){
    int fmt=detect_format(fp);
    if(fmt==FORMAT_UNK){skipping("%s unrecognized format",fname);return;}
    uint64_t comp_size=0,uncomp_size=0;
    uint32_t check=0;
    time_t mtime=0;
    char*name=NULL;
    char method[32]="";
    if(fmt==FORMAT_GZIP){
        /* get file size if seekable */
        long start=ftell(fp);
        fseek(fp,0,SEEK_END);long end=ftell(fp);
        fseek(fp,start,SEEK_SET);
        if(end>0&&start>=0)comp_size=(uint64_t)(end-start);
        /* read header */
        char*nm=NULL;time_t mt=0;
        if(read_gz_hdr(fp,&nm,&mt,NULL)!=0){skipping("%s unrecognized format",fname);return;}
        mtime=mt;
        if(nm)name=nm;
        /* inflate to /dev/null counting bytes */
        uint32_t crc=0;uint64_t len=0;
        inflate_stream(fp,NULL,&crc,&len);
        uncomp_size=len;check=crc;
        uint32_t fcrc,flen;r32(fp,&fcrc);r32(fp,&flen);
        check=fcrc;
        /* strip path from fname for display */
        const char*bn=strrchr(fname,'/');bn=bn?bn+1:fname;
        /* strip suffix */
        char dname[4096];strncpy(dname,bn,sizeof(dname)-1);dname[sizeof(dname)-1]=0;
        char*dot=strrchr(dname,'.');if(dot)*dot=0;
        if(!name)name=strdup(dname);
        strcpy(method,"gzip");
        char method_full[64];
        snprintf(method_full,sizeof(method_full),"gzip %d",g_level);
        /* print */
        if(g_verbose){
            char tsbuf[32]="------ -----";
            if(mtime){
                struct tm*tm=localtime(&mtime);
                if(tm)strftime(tsbuf,sizeof(tsbuf),"%b %d %H:%M",tm);
            }
            printf("%-6s %-8s %8s %12llu %12llu %6.1f%%  %s\n",
                "method","check","timestamp",
                (unsigned long long)comp_size,(unsigned long long)uncomp_size,0.0,"name");
            /* Actually print the header on first call... let's do it differently */
        }
        /* percentage reduction */
        double red=0;
        if(uncomp_size>0)red=100.0*(1.0-(double)comp_size/(double)uncomp_size);
        if(g_verbose){
            char tsbuf[32]="------ -----";
            if(mtime){struct tm*tm=localtime(&mtime);if(tm)strftime(tsbuf,sizeof(tsbuf),"%b %d %H:%M",tm);}
            printf("gzip %-2d %08x  %-13s %12llu %12llu %6.1f%%  %s\n",
                8,check,tsbuf,
                (unsigned long long)comp_size,(unsigned long long)uncomp_size,
                red,name);
        } else {
            printf("%12llu %12llu %6.1f%%  %s\n",
                (unsigned long long)comp_size,(unsigned long long)uncomp_size,
                red,name);
        }
        free(name);
    }
}

/* ======== File handling ======== */

static char* get_suffix(void) { return g_suffix ? g_suffix : (g_format==FMT_ZLIB?".zz":g_format==FMT_ZIP?".zip":".gz"); }

static char* make_out_name(const char*in, const char*suf) {
    size_t n=strlen(in)+strlen(suf)+1;
    char*r=malloc(n); if(!r)die("out of memory");
    strcpy(r,in); strcat(r,suf);
    return r;
}

static char* strip_suffix(const char*fname, const char*suf) {
    size_t fl=strlen(fname),sl=strlen(suf);
    if(fl<=sl)return NULL;
    if(strcasecmp(fname+fl-sl,suf)!=0)return NULL;
    char*r=malloc(fl-sl+1);if(!r)die("out of memory");
    memcpy(r,fname,fl-sl);r[fl-sl]=0;
    return r;
}

static int is_known_suffix(const char*fname){
    const char*exts[]={"gz","zz","zip","tgz","taz",NULL};
    const char*dot=strrchr(fname,'.');
    if(!dot)return 0;
    dot++;
    for(int i=0;exts[i];i++)if(strcasecmp(dot,exts[i])==0)return 1;
    return 0;
}

static void process_file(const char*fname);
static void process_dir(const char*dname);

static void compress_file(const char*fname){
    /* check if regular file */
    struct stat st;
    if(stat(fname,&st)!=0){skipping("%s does not exist",fname);return;}
    if(!S_ISREG(st.st_mode)&&!g_force){skipping("%s is a special file or device",fname);return;}
    /* determine output name */
    const char*suf=get_suffix();
    char*outname=make_out_name(fname,suf);
    /* check if output exists */
    if(!g_force&&!g_test){
        struct stat ost;
        if(stat(outname,&ost)==0){skipping("%s exists",outname);free(outname);return;}
    }
    FILE*in=fopen(fname,"rb");
    if(!in){skipping("%s %s",fname,strerror(errno));free(outname);return;}
    if(g_verbose)fprintf(stderr,"%s to %s \n",fname,outname);
    FILE*out=fopen(outname,"wb");
    if(!out){skipping("%s %s",outname,strerror(errno));fclose(in);free(outname);return;}
    g_outpath=outname;
    const char*base=strrchr(fname,'/');base=base?base+1:fname;
    time_t mt=st.st_mtime;
    do_compress(in,out,base,mt);
    fclose(in); fclose(out);
    if(g_sync){int fd=open(outname,O_RDONLY);if(fd>=0){fsync(fd);close(fd);}}
    /* set mtime on output to match input */
    struct utimbuf ut;ut.actime=st.st_atime;ut.modtime=st.st_mtime;
    utime(outname,&ut);
    if(!g_keep)remove(fname);
    g_outpath=NULL;
    free(outname);
}

static void decompress_file(const char*fname){
    struct stat st;
    if(stat(fname,&st)!=0){skipping("%s does not exist",fname);return;}
    if(!S_ISREG(st.st_mode)&&!g_force){skipping("%s is a special file or device",fname);return;}
    /* determine output name by stripping suffix */
    const char*suf=g_suffix?g_suffix:NULL;
    char*outname=NULL;
    /* try known suffixes */
    if(suf){
        /* check file has that suffix */
        outname=strip_suffix(fname,suf);
        if(!outname){skipping("%s does not have compressed suffix",fname);return;}
    } else {
        /* try .gz, .zz, .zip, .tgz, .taz */
        struct { const char*ext; } exts[]={
            {".gz"},{".zz"},{".zip"},{".tgz"},{".taz"},{NULL}
        };
        for(int i=0;exts[i].ext;i++){
            outname=strip_suffix(fname,exts[i].ext);
            if(outname)break;
        }
        if(!outname){skipping("%s does not have compressed suffix",fname);return;}
    }
    /* check if output exists */
    if(!g_force&&!g_test){
        struct stat ost;
        if(stat(outname,&ost)==0){skipping("%s exists",outname);free(outname);return;}
    }
    FILE*in=fopen(fname,"rb");
    if(!in){skipping("%s %s",fname,strerror(errno));free(outname);return;}
    int fmt=detect_format(in);
    if(fmt==FORMAT_UNK){skipping("%s unrecognized format",fname);fclose(in);free(outname);return;}
    FILE*out=NULL;
    if(!g_test){
        if(g_verbose)fprintf(stderr,"%s to %s \n",fname,outname);
        out=fopen(outname,"wb");
        if(!out){skipping("%s %s",outname,strerror(errno));fclose(in);free(outname);return;}
        g_outpath=outname;
    } else {
        if(g_verbose)fprintf(stderr,"%s ok\n",fname);
    }
    int ret=0;
    char*dname=NULL;time_t dmt=0;
    if(fmt==FORMAT_GZIP)ret=do_decompress_gz(in,out,fname,&dname,&dmt);
    else if(fmt==FORMAT_ZLIB)ret=do_decompress_zlib(in,out);
    else if(fmt==FORMAT_ZIP)ret=do_decompress_zip(in,out,&dname,&dmt);
    fclose(in);
    if(out)fclose(out);
    if(ret!=0){
        if(!g_quiet)fprintf(stderr,"%s: error decompressing %s\n",prog,fname);
        if(out&&!g_test)remove(outname);
        g_ret=1;
    } else {
        if(!g_test){
            /* restore mtime */
            time_t use_mt=dmt?dmt:st.st_mtime;
            struct utimbuf ut;ut.actime=st.st_atime;ut.modtime=use_mt;
            utime(outname,&ut);
            if(!g_keep)remove(fname);
        }
    }
    free(dname);
    g_outpath=NULL;
    free(outname);
}

static void list_file(const char*fname){
    struct stat st;
    if(stat(fname,&st)!=0){skipping("%s does not exist",fname);return;}
    FILE*fp=fopen(fname,"rb");
    if(!fp){skipping("%s %s",fname,strerror(errno));return;}
    do_list(fp,fname);
    fclose(fp);
}

static void process_file(const char*fname){
    if(g_list){list_file(fname);return;}
    if(g_decomp||g_test){decompress_file(fname);return;}
    compress_file(fname);
}

static void process_dir(const char*dname){
    DIR*d=opendir(dname);
    if(!d){skipping("%s %s",dname,strerror(errno));return;}
    struct dirent*e;
    while((e=readdir(d))!=NULL){
        if(strcmp(e->d_name,".")==0||strcmp(e->d_name,"..")==0)continue;
        char path[4096];
        snprintf(path,sizeof(path),"%s/%s",dname,e->d_name);
        struct stat st;
        if(stat(path,&st)!=0)continue;
        if(S_ISDIR(st.st_mode)&&g_recur)process_dir(path);
        else if(S_ISREG(st.st_mode))process_file(path);
    }
    closedir(d);
}

/* ======== Argument parsing ======== */

static void parse_opts(int argc, char**argv, int start, int*file_start_out) {
    int i;
    for(i=start;i<argc;i++){
        char*a=argv[i];
        if(strcmp(a,"--")==0){i++;break;}
        if(a[0]!='-'||a[1]==0)break;
        /* long options */
        if(a[1]=='-'){
            if(strcmp(a,"--fast")==0)g_level=1;
            else if(strcmp(a,"--best")==0)g_level=9;
            else if(strcmp(a,"--decompress")==0||strcmp(a,"--uncompress")==0)g_decomp=1;
            else if(strcmp(a,"--stdout")==0||strcmp(a,"--to-stdout")==0)g_keep=1,g_format=g_format;
            else if(strcmp(a,"--force")==0)g_force=1;
            else if(strcmp(a,"--help")==0){
                printf("Usage: %s [options] [files ...]\n",prog);
                printf("  will compress files in place, adding the suffix '.gz'. If no files are\n");
                printf("  specified, stdin will be compressed to stdout. pigz does what gzip does,\n");
                printf("  but spreads the work over multiple processors and cores when compressing.\n\n");
                printf("Options:\n");
                printf("  -0 to -9, -11        Compression level (level 11, zopfli, is much slower)\n");
                printf("  --fast, --best       Compression levels 1 and 9 respectively\n");
                printf("  -A, --alias xxx      Use xxx as the name for any --zip entry from stdin\n");
                printf("  -b, --blocksize mmm  Set compression block size to mmmK (default 128K)\n");
                printf("  -c, --stdout         Write all processed output to stdout (won't delete)\n");
                printf("  -C, --comment ccc    Put comment ccc in the gzip or zip header\n");
                printf("  -d, --decompress     Decompress the compressed input\n");
                printf("  -f, --force          Force overwrite, compress .gz, links, and to terminal\n");
                printf("  -F  --first          Do iterations first, before block split for -11\n");
                printf("  -h, --help           Display a help screen and quit\n");
                printf("  -H, --huffman        Use only Huffman coding for compression\n");
                printf("  -i, --independent    Compress blocks independently for damage recovery\n");
                printf("  -I, --iterations n   Number of iterations for -11 optimization\n");
                printf("  -J, --maxsplits n    Maximum number of split blocks for -11\n");
                printf("  -k, --keep           Do not delete original file after processing\n");
                printf("  -K, --zip            Compress to PKWare zip (.zip) single entry format\n");
                printf("  -l, --list           List the contents of the compressed input\n");
                printf("  -L, --license        Display the pigz license and quit\n");
                printf("  -m, --no-time        Do not store or restore mod time\n");
                printf("  -M, --time           Store or restore mod time\n");
                printf("  -n, --no-name        Do not store or restore file name or mod time\n");
                printf("  -N, --name           Store or restore file name and mod time\n");
                printf("  -O  --oneblock       Do not split into smaller blocks for -11\n");
                printf("  -p, --processes n    Allow up to n compression threads (default is the\n");
                printf("                       number of online processors, or 8 if unknown)\n");
                printf("  -q, --quiet          Print no messages, even on error\n");
                printf("  -r, --recursive      Process the contents of all subdirectories\n");
                printf("  -R, --rsyncable      Input-determined block locations for rsync\n");
                printf("  -S, --suffix .sss    Use suffix .sss instead of .gz (for compression)\n");
                printf("  -t, --test           Test the integrity of the compressed input\n");
                printf("  -U, --rle            Use run-length encoding for compression\n");
                printf("  -v, --verbose        Provide more verbose output\n");
                printf("  -V  --version        Show the version of pigz\n");
                printf("  -Y  --synchronous    Force output file write to permanent storage\n");
                printf("  -z, --zlib           Compress to zlib (.zz) instead of gzip format\n");
                printf("  --                   All arguments after \"--\" are treated as files\n");
                exit(0);
            }
            else if(strcmp(a,"--independent")==0)g_indep=1;
            else if(strcmp(a,"--keep")==0)g_keep=1;
            else if(strcmp(a,"--zip")==0)g_format=FMT_ZIP;
            else if(strcmp(a,"--list")==0)g_list=1;
            else if(strcmp(a,"--license")==0){
                printf("pigz %s\nCopyright (C) 2007-2023 Mark Adler\nSubject to the terms of the zlib license.\nNo warranty is provided or implied.\n",PIGZ_VERSION);
                exit(0);
            }
            else if(strcmp(a,"--no-time")==0)g_mtime=0;
            else if(strcmp(a,"--time")==0)g_mtime=1;
            else if(strcmp(a,"--no-name")==0){g_name=0;g_mtime=0;}
            else if(strcmp(a,"--name")==0){g_name=1;g_mtime=1;}
            else if(strcmp(a,"--quiet")==0||strcmp(a,"--silent")==0)g_quiet=1;
            else if(strcmp(a,"--recursive")==0)g_recur=1;
            else if(strcmp(a,"--rsyncable")==0)g_rsync=1;
            else if(strcmp(a,"--test")==0){g_test=1;g_decomp=1;}
            else if(strcmp(a,"--rle")==0)g_rle=1;
            else if(strcmp(a,"--huffman")==0)g_huffman=1;
            else if(strcmp(a,"--verbose")==0)g_verbose++;
            else if(strcmp(a,"--version")==0){printf("pigz %s\n",PIGZ_VERSION);exit(0);}
            else if(strcmp(a,"--zlib")==0)g_format=FMT_ZLIB;
            else if(strcmp(a,"--synchronous")==0)g_sync=1;
            else if(strcmp(a,"--first")==0){}
            else if(strcmp(a,"--oneblock")==0){}
            else if(strcmp(a,"--alias")==0){i++;if(i<argc)g_alias=argv[i];}
            else if(strncmp(a,"--alias=",8)==0)g_alias=a+8;
            else if(strcmp(a,"--comment")==0){i++;if(i<argc)g_comment=argv[i];}
            else if(strncmp(a,"--comment=",10)==0)g_comment=a+10;
            else if(strcmp(a,"--blocksize")==0){i++;if(i<argc)g_block=atoi(argv[i])*1024;}
            else if(strncmp(a,"--blocksize=",12)==0)g_block=atoi(a+12)*1024;
            else if(strcmp(a,"--processes")==0){i++;if(i<argc)g_procs=atoi(argv[i]);}
            else if(strncmp(a,"--processes=",12)==0)g_procs=atoi(a+12);
            else if(strcmp(a,"--suffix")==0){i++;if(i<argc)g_suffix=argv[i];}
            else if(strncmp(a,"--suffix=",9)==0)g_suffix=a+9;
            else if(strcmp(a,"--iterations")==0){i++;/* skip */}
            else if(strcmp(a,"--maxsplits")==0){i++;/* skip */}
            else{if(!g_quiet)fprintf(stderr,"%s: invalid option: %s\n",prog,a);g_ret=1;}
            continue;
        }
        /* short options */
        for(int j=1;a[j];j++){
            char c=a[j];
            if(c>='0'&&c<='9'){g_level=c-'0';continue;}
            if(c=='A'){if(a[j+1])g_alias=a+j+1;else{i++;if(i<argc)g_alias=argv[i];}break;}
            if(c=='b'){if(a[j+1])g_block=atoi(a+j+1)*1024;else{i++;if(i<argc)g_block=atoi(argv[i])*1024;}break;}
            if(c=='c'){g_keep=1;/* stdout mode handled below */continue;}/* handled in main */
            if(c=='C'){if(a[j+1])g_comment=a+j+1;else{i++;if(i<argc)g_comment=argv[i];}break;}
            if(c=='d'){g_decomp=1;continue;}
            if(c=='f'){g_force=1;continue;}
            if(c=='F')continue;/* zopfli first */
            if(c=='h'){/* print help and exit - call long handler */argv[i]=(char*)"--help";j=0;i--;break;}
            if(c=='H'){g_huffman=1;continue;}
            if(c=='i'){g_indep=1;continue;}
            if(c=='I'){if(a[j+1])||(i+1<argc&&!g_quiet){if(!a[j+1])i++;}break;}
            if(c=='J'){if(!a[j+1])i++;break;}
            if(c=='k'){g_keep=1;continue;}
            if(c=='K'){g_format=FMT_ZIP;continue;}
            if(c=='l'){g_list=1;continue;}
            if(c=='L'){printf("pigz %s\nCopyright (C) 2007-2023 Mark Adler\nSubject to the terms of the zlib license.\nNo warranty is provided or implied.\n",PIGZ_VERSION);exit(0);}
            if(c=='m'){g_mtime=0;continue;}
            if(c=='M'){g_mtime=1;continue;}
            if(c=='n'){g_name=0;g_mtime=0;continue;}
            if(c=='N'){g_name=1;g_mtime=1;continue;}
            if(c=='O')continue;
            if(c=='p'){if(a[j+1])g_procs=atoi(a+j+1);else{i++;if(i<argc)g_procs=atoi(argv[i]);}break;}
            if(c=='q'){g_quiet=1;continue;}
            if(c=='r'){g_recur=1;continue;}
            if(c=='R'){g_rsync=1;continue;}
            if(c=='S'){if(a[j+1])g_suffix=a+j+1;else{i++;if(i<argc)g_suffix=argv[i];}break;}
            if(c=='t'){g_test=1;g_decomp=1;continue;}
            if(c=='U'){g_rle=1;continue;}
            if(c=='v'){g_verbose++;continue;}
            if(c=='V'){
                printf("pigz %s\n",PIGZ_VERSION);
                /* -vV also shows zlib version */
                if(g_verbose)printf("zlib %s\n",zlibVersion());
                exit(0);
            }
            if(c=='Y'){g_sync=1;continue;}
            if(c=='z'){g_format=FMT_ZLIB;continue;}
            if(!g_quiet)fprintf(stderr,"%s: invalid option: -%c\n",prog,c);
            g_ret=1;
        }
    }
    if(file_start_out)*file_start_out=i;
}

/* ======== stdin/stdout compression ======== */
static void compress_stdin(void){
    do_compress(stdin,stdout,NULL,0);
}
static void decompress_stdin(void){
    int fmt=detect_format(stdin);
    if(fmt==FORMAT_UNK){skipping("<stdin> unrecognized format");return;}
    char*name=NULL;time_t mt=0;
    int ret=0;
    if(fmt==FORMAT_GZIP)ret=do_decompress_gz(stdin,stdout,NULL,&name,&mt);
    else if(fmt==FORMAT_ZLIB)ret=do_decompress_zlib(stdin,stdout);
    else if(fmt==FORMAT_ZIP)ret=do_decompress_zip(stdin,stdout,&name,&mt);
    if(ret!=0){if(!g_quiet)fprintf(stderr,"%s: error decompressing stdin\n",prog);g_ret=1;}
    free(name);
}
static void list_stdin(void){
    printf("compressed   original reduced  name\n");
    do_list(stdin,"<stdin>");
}
static void test_stdin(void){
    int fmt=detect_format(stdin);
    if(fmt==FORMAT_UNK){skipping("<stdin> unrecognized format");return;}
    char*name=NULL;time_t mt=0;
    int ret=0;
    if(fmt==FORMAT_GZIP)ret=do_decompress_gz(stdin,NULL,NULL,&name,&mt);
    else if(fmt==FORMAT_ZLIB)ret=do_decompress_zlib(stdin,NULL);
    else if(fmt==FORMAT_ZIP)ret=do_decompress_zip(stdin,NULL,&name,&mt);
    if(ret!=0){if(!g_quiet)fprintf(stderr,"%s: error testing stdin\n",prog);g_ret=1;}
    free(name);
}

/* ======== main ======== */
int main(int argc,char**argv){
    /* set prog name */
