/* inflate a raw deflate stream, writing to out. Returns 0 ok, -1 error */
static int inflate_stream(FILE*in,FILE*out,uint32_t*crc_out,uint64_t*len_out){
    z_stream s;memset(&s,0,sizeof(s));
