    uint32_t crc=crc32(0,NULL,0);
    uint64_t total=0;
    unsigned char ibuf[65536],obuf[65536];
    int done=0,ret=Z_OK;
    while(!done){
        if(!s.avail_in){
            s.next_in=ibuf;
            s.avail_in=(uInt)fread(ibuf,1,sizeof(ibuf),in);
            if(!s.avail_in)break;
