        /* rewind and re-read header */
        if(read_gz_hdr(fp,&name,&mtime)!=0){
            skipping("%s unrecognized format",dispname);return;
        }
        hdr_end=ftell(fp);

        /* inflate discarding output */
        uint32_t crc=0;uint64_t len=0;
        inflate_to(fp,NULL,&crc,&len);
        uncomp_size=len;
        long data_end=ftell(fp);

        /* read trailer to get CRC */
        uint32_t fcrc,flen;
        if(r32(fp,&fcrc)==0&&r32(fp,&flen)==0){
            check=fcrc;
        }

        /* compressed size = data between header and trailer */
        if(hdr_end>=0&&data_end>=0)
            comp_size=(uint64_t)(data_end-hdr_end);

        /* determine name */
        if(!name){
            /* derive from filename */
            const char*bn=strrchr(dispname,'/');bn=bn?bn+1:dispname;
            char tmp[4096];strncpy(tmp,bn,sizeof(tmp)-1);tmp[sizeof(tmp)-1]=0;
            char*dot=strrchr(tmp,'.');if(dot)*dot=0;
            name=strdup(tmp);
        }
        strcpy(method_str,"gzip");
        method_level=8;
    } else if(fmt==DFMT_ZIP){
        uint32_t sig;r32(fp,&sig);
        if(sig!=0x04034b50){skipping("%s unrecognized format",dispname);return;}
        uint16_t ver,flg,meth,dt,dd;
        r16(fp,&ver);r16(fp,&flg);r16(fp,&meth);r16(fp,&dt);r16(fp,&dd);
        uint32_t crc32v,compsz,uncompsz;
        r32(fp,&crc32v);r32(fp,&compsz);r32(fp,&uncompsz);
        uint16_t nlen,elen;r16(fp,&nlen);r16(fp,&elen);
        if(nlen>0){name=malloc(nlen+1);fread(name,1,nlen,fp);name[nlen]=0;}
        for(int i=0;i<(int)elen;i++)rb(fp);

        uint32_t crc=0;uint64_t len=0;
        long dstart=ftell(fp);
        inflate_to(fp,NULL,&crc,&len);
        long dend=ftell(fp);
        uncomp_size=len;comp_size=(uint64_t)(dend-dstart);
        check=crc;
        if(!name)name=strdup(dispname);
        strcpy(method_str,"zip");method_level=8;
    } else if(fmt==DFMT_ZLIB){
        rb(fp);rb(fp);
        uint32_t crc=0;uint64_t len=0;
        long dstart=ftell(fp);
        inflate_to(fp,NULL,&crc,&len);
        long dend=ftell(fp);
        uncomp_size=len;comp_size=(uint64_t)(dend-dstart);
        check=crc;
        name=strdup(dispname);
        strcpy(method_str,"zlib");method_level=8;
    }

    double red=uncomp_size>0?(1.0-(double)comp_size/(double)uncomp_size)*100.0:0.0;

    if(g_verbose){
        char ts[32]="------ -----";
        if(mtime){struct tm*tm=localtime(&mtime);if(tm)strftime(ts,sizeof(ts),"%b %d %H:%M",tm);}
        printf("%-4s %-2d  %08x  %-12s%12llu %10llu%7.1f%%  %s\n",
            method_str,method_level,check,ts,
            (unsigned long long)comp_size,(unsigned long long)uncomp_size,
            red,name?name:"");
    } else {
        printf("%10llu %10llu%7.1f%%  %s\n",
            (unsigned long long)comp_size,(unsigned long long)uncomp_size,
            red,name?name:"");
    }
    free(name);
}

/* ============================================================ */
/* File handling helpers */

static const char*get_suffix(void){
    return g_suffix?g_suffix:(g_format==FMT_ZLIB?".zz":g_format==FMT_ZIP?".zip":".gz");
}

/* Try to strip a known decompression suffix. Returns new name or NULL. */
static char*make_deconame(const char*fname){
    size_t n=strlen(fname);
    /* Special: .tgz -> .tar */
    if(n>4&&strcasecmp(fname+n-4,".tgz")==0){
        char*r=malloc(n-1);if(!r)die("out of memory");
        memcpy(r,fname,n-4);memcpy(r+n-4,".tar",4);r[n]=0;
        return r;
    }
    /* Accepted suffixes that just get stripped */
    const char*ok[]={".gz",".zz",".zip",".Z",NULL};
    for(int i=0;ok[i];i++){
        size_t sl=strlen(ok[i]);
        if(n>sl&&strcasecmp(fname+n-sl,ok[i])==0){
            char*r=malloc(n-sl+1);if(!r)die("out of memory");
            memcpy(r,fname,n-sl);r[n-sl]=0;
            return r;
        }
    }
    return NULL;
}

/* Strip the last .ext from a filename (for decompression to file) */
static char*strip_last_ext(const char*fname){
    const char*dot=strrchr(fname,'.');
    if(!dot||dot==fname)return NULL;
    /* Don't allow empty basename */
    char*r=malloc(dot-fname+1);if(!r)die("out of memory");
    memcpy(r,fname,dot-fname);r[dot-fname]=0;
    return r;
}

/* ============================================================ */
/* File operations */

static void compress_file(const char*fname,int to_stdout){
    struct stat st;
    if(stat(fname,&st)!=0){skipping("%s does not exist",fname);return;}
    if(!S_ISREG(st.st_mode)&&!g_force){skipping("%s is a special file or device",fname);return;}
    const char*suf=get_suffix();
    size_t fnlen=strlen(fname),suflen=strlen(suf);
    /* Check if file ends with output suffix */
    if(!g_force&&fnlen>=suflen&&strcasecmp(fname+fnlen-suflen,suf)==0){
        skipping("%s ends with %s",fname,suf);return;
    }
    FILE*in=fopen(fname,"rb");
    if(!in){skipping("%s %s",fname,strerror(errno));return;}
    if(to_stdout){
        const char*base=strrchr(fname,'/');base=base?base+1:fname;
        do_compress(in,stdout,base,st.st_mtime);
        fclose(in);
        return;
    }
    char*outname=malloc(fnlen+suflen+1);
    if(!outname)die("out of memory");
    memcpy(outname,fname,fnlen);
    memcpy(outname+fnlen,suf,suflen+1);
    if(!g_force){
        struct stat ost;
        if(stat(outname,&ost)==0){skipping("%s exists",outname);fclose(in);free(outname);return;}
    }
    if(g_verbose)fprintf(stderr,"%s to %s \n",fname,outname);
    FILE*out=fopen(outname,"wb");
    if(!out){skipping("%s %s",outname,strerror(errno));fclose(in);free(outname);return;}
    g_outpath=outname;
    const char*base=strrchr(fname,'/');base=base?base+1:fname;
    do_compress(in,out,base,st.st_mtime);
    fclose(in);fclose(out);
    if(g_sync){int fd=open(outname,O_RDONLY);if(fd>=0){fsync(fd);close(fd);}}
    struct utimbuf ut;ut.actime=st.st_atime;ut.modtime=st.st_mtime;
    utime(outname,&ut);
    if(!g_keep)remove(fname);
    g_outpath=NULL;
    free(outname);
}

static void decompress_file(const char*fname,int to_stdout,int test_mode){
    struct stat st;
    if(stat(fname,&st)!=0){skipping("%s does not exist",fname);return;}
    if(!S_ISREG(st.st_mode)&&!g_force){skipping("%s is a special file or device",fname);return;}
    FILE*in=fopen(fname,"rb");
    if(!in){skipping("%s %s",fname,strerror(errno));return;}
    int fmt=detect_fmt(in);
    if(fmt<0){
        if(fmt==-2)skipping("%s empty",fname);
        else skipping("%s unrecognized format",fname);
        fclose(in);return;
    }
    if(to_stdout||test_mode){
        char*name=NULL;time_t mt=0;int r=0;
        if(fmt==DFMT_GZIP)r=decomp_gz_file(in,test_mode?NULL:stdout,&name,&mt);
        else if(fmt==DFMT_ZLIB)r=decomp_zlib(in,test_mode?NULL:stdout);
        else if(fmt==DFMT_ZIP)r=decomp_zip(in,test_mode?NULL:stdout,&name,&mt);
        else{skipping("%s unrecognized format",fname);fclose(in);return;}
        if(r){skipping("%s invalid compressed data",fname);}
        free(name);fclose(in);return;
    }
    /* Determine output filename */
    char*outname=make_deconame(fname);
    if(!outname){skipping("%s does not have compressed suffix",fname);fclose(in);return;}
    if(!g_force){
        struct stat ost;
        if(stat(outname,&ost)==0){skipping("%s exists",outname);fclose(in);free(outname);return;}
    }
    if(g_verbose)fprintf(stderr,"%s to %s \n",fname,outname);
    FILE*out=fopen(outname,"wb");
    if(!out){skipping("%s %s",outname,strerror(errno));fclose(in);free(outname);return;}
    g_outpath=outname;
    char*name=NULL;time_t mt=0;int r=0;
    if(fmt==DFMT_GZIP)r=decomp_gz_file(in,out,&name,&mt);
    else if(fmt==DFMT_ZLIB)r=decomp_zlib(in,out);
    else if(fmt==DFMT_ZIP)r=decomp_zip(in,out,&name,&mt);
    else r=-1;
    fclose(in);fclose(out);
    if(r){
        skipping("%s invalid compressed data",fname);
        remove(outname);
    } else {
        time_t use_mt=mt?mt:st.st_mtime;
        struct utimbuf ut;ut.actime=st.st_atime;ut.modtime=use_mt;
        utime(outname,&ut);
        if(!g_keep)remove(fname);
    }
    free(name);
    g_outpath=NULL;
    free(outname);
}

static void list_file(const char*fname){
    struct stat st;
    if(stat(fname,&st)!=0){skipping("%s does not exist",fname);return;}
    FILE*fp=fopen(fname,"rb");
    if(!fp){skipping("%s %s",fname,strerror(errno));return;}
    /* display name: use path without suffix */
    const char*bn=strrchr(fname,'/');bn=bn?bn+1:fname;
    char dispbuf[4096];strncpy(dispbuf,bn,sizeof(dispbuf)-1);dispbuf[sizeof(dispbuf)-1]=0;
    /* strip last extension for display */
    char*dot=strrchr(dispbuf,'.');if(dot)*dot=0;
    do_list(fp,dispbuf);
    fclose(fp);
}

static void process_file(const char*fname,int to_stdout){
    if(g_list){list_file(fname);return;}
    if(g_test){decompress_file(fname,0,1);return;}
    if(g_decomp){decompress_file(fname,to_stdout,0);return;}
    compress_file(fname,to_stdout);
}

static void process_dir(const char*dname){
    DIR*d=opendir(dname);
    if(!d){skipping("%s %s",dname,strerror(errno));return;}
    struct dirent*e;
    while((e=readdir(d))!=NULL){
        if(!strcmp(e->d_name,".")||!strcmp(e->d_name,".."))continue;
        char path[4096];
        snprintf(path,sizeof(path),"%s/%s",dname,e->d_name);
        struct stat st;if(stat(path,&st)!=0)continue;
        if(S_ISDIR(st.st_mode))process_dir(path);
        else if(S_ISREG(st.st_mode))process_file(path,0);
    }
    closedir(d);
}

/* ============================================================ */
/* stdin/stdout operations */

static void do_stdin(int to_stdout){
    if(g_list){
        do_list(stdin,"<stdin>");
        return;
    }
    if(g_test){
        int fmt=detect_fmt(stdin);
        if(fmt==-2){skipping("<stdin> empty");return;}
        if(fmt==DFMT_UNK){skipping("<stdin> unrecognized format");return;}
        int r=0;char*nm=NULL;time_t mt=0;
        if(fmt==DFMT_GZIP)r=decomp_gz(stdin,NULL,&nm,&mt);
        else if(fmt==DFMT_ZLIB)r=decomp_zlib(stdin,NULL);
        else r=decomp_zip(stdin,NULL,&nm,&mt);
        if(r<0&&r!=-2){if(!g_quiet)fprintf(stderr,"%s: error testing <stdin>\n",prog);g_ret=1;}
        free(nm);
        return;
    }
    if(g_decomp){
        int fmt=detect_fmt(stdin);
        if(fmt==-2){skipping("<stdin> empty");return;}
        if(fmt==DFMT_UNK){skipping("<stdin> unrecognized format");return;}
        int r=0;char*nm=NULL;time_t mt=0;
        if(fmt==DFMT_GZIP)r=decomp_gz(stdin,stdout,&nm,&mt);
        else if(fmt==DFMT_ZLIB)r=decomp_zlib(stdin,stdout);
        else r=decomp_zip(stdin,stdout,&nm,&mt);
        if(r<0&&r!=-2){if(!g_quiet)fprintf(stderr,"%s: error decompressing <stdin>\n",prog);g_ret=1;}
        free(nm);
        return;
    }
    /* compress stdin to stdout */
    do_compress(stdin,stdout,NULL,0);
}

/* ============================================================ */
/* Argument parsing */

static void show_help(void){
    printf("Usage: %s [options] [files ...]\n",prog);
    printf("  will compress files in place, adding the suffix '.gz'. If no files are\n");
    printf("  specified, stdin will be compressed to stdout. pigz does what gzip does,\n");
    printf("  but spreads the work over multiple processors and cores when compressing.\n\n");
    printf("Options:\n");
    printf("  -0 to -9, -11        Compression level (level 11, zopfli, is much slower)\n");
    printf("  --fast, --best       Compression levels 1 and 9 respectively\n");
    printf("  -A, --alias xxx      Use xxx as the name for any --zip entry from stdin\n");
    printf("  -b, --blocksize mmm  Set compression block size to mmmK (default 128K)\n");
    printf("  -c, --stdout         Write all processed output to stdout (won't delete)\n");
    printf("  -C, --comment ccc    Put comment ccc in the gzip or zip header\n");
    printf("  -d, --decompress     Decompress the compressed input\n");
    printf("  -f, --force          Force overwrite, compress .gz, links, and to terminal\n");
    printf("  -F  --first          Do iterations first, before block split for -11\n");
    printf("  -h, --help           Display a help screen and quit\n");
    printf("  -H, --huffman        Use only Huffman coding for compression\n");
    printf("  -i, --independent    Compress blocks independently for damage recovery\n");
    printf("  -I, --iterations n   Number of iterations for -11 optimization\n");
    printf("  -J, --maxsplits n    Maximum number of split blocks for -11\n");
    printf("  -k, --keep           Do not delete original file after processing\n");
    printf("  -K, --zip            Compress to PKWare zip (.zip) single entry format\n");
    printf("  -l, --list           List the contents of the compressed input\n");
    printf("  -L, --license        Display the pigz license and quit\n");
    printf("  -m, --no-time        Do not store or restore mod time\n");
    printf("  -M, --time           Store or restore mod time\n");
    printf("  -n, --no-name        Do not store or restore file name or mod time\n");
    printf("  -N, --name           Store or restore file name and mod time\n");
    printf("  -O  --oneblock       Do not split into smaller blocks for -11\n");
    printf("  -p, --processes n    Allow up to n compression threads (default is the\n");
    printf("                       number of online processors, or 8 if unknown)\n");
    printf("  -q, --quiet          Print no messages, even on error\n");
    printf("  -r, --recursive      Process the contents of all subdirectories\n");
    printf("  -R, --rsyncable      Input-determined block locations for rsync\n");
    printf("  -S, --suffix .sss    Use suffix .sss instead of .gz (for compression)\n");
    printf("  -t, --test           Test the integrity of the compressed input\n");
    printf("  -U, --rle            Use run-length encoding for compression\n");
    printf("  -v, --verbose        Provide more verbose output\n");
    printf("  -V  --version        Show the version of pigz\n");
    printf("  -Y  --synchronous    Force output file write to permanent storage\n");
    printf("  -z, --zlib           Compress to zlib (.zz) instead of gzip format\n");
    printf("  --                   All arguments after \"--\" are treated as files\n");
    exit(0);
}

typedef struct { int argc; char**argv; int i; } Pargs;

static int get_arg_str(Pargs*p, char **out, const char*opt_rest) {
    if(opt_rest&&*opt_rest){*out=(char*)opt_rest;return 0;}
    if(p->i+1<p->argc){p->i++;*out=p->argv[p->i];return 0;}
    if(!g_quiet)fprintf(stderr,"%s: %s requires an argument\n",prog,p->argv[p->i]);
    return -1;
}

static void parse_opts(int argc,char**argv,int start,int*end){
    Pargs p={argc,argv,start};
    for(;p.i<argc;p.i++){
        char*a=argv[p.i];
        if(!strcmp(a,"--")){p.i++;break;}
        if(a[0]!='-'||!a[1])break;
        if(a[1]=='-'){
            /* long options */
            if(!strcmp(a,"--fast"))g_level=1;
            else if(!strcmp(a,"--best"))g_level=9;
            else if(!strcmp(a,"--decompress")||!strcmp(a,"--uncompress"))g_decomp=1;
            else if(!strcmp(a,"--stdout")||!strcmp(a,"--to-stdout")){/* handled in main */}
            else if(!strcmp(a,"--force"))g_force=1;
            else if(!strcmp(a,"--help"))show_help();
            else if(!strcmp(a,"--independent"))g_indep=1;
            else if(!strcmp(a,"--keep"))g_keep=1;
            else if(!strcmp(a,"--zip"))g_format=FMT_ZIP;
            else if(!strcmp(a,"--list"))g_list=1;
            else if(!strcmp(a,"--license")){printf("pigz %s\nCopyright (C) 2007-2023 Mark Adler\nSubject to the terms of the zlib license.\nNo warranty is provided or implied.\n",PIGZ_VERSION);exit(0);}
            else if(!strcmp(a,"--no-time"))g_mtime=0;
            else if(!strcmp(a,"--time"))g_mtime=1;
            else if(!strcmp(a,"--no-name")){g_name=0;g_mtime=0;}
            else if(!strcmp(a,"--name")){g_name=1;g_mtime=1;}
            else if(!strcmp(a,"--quiet")||!strcmp(a,"--silent"))g_quiet=1;
            else if(!strcmp(a,"--recursive"))g_recur=1;
            else if(!strcmp(a,"--rsyncable"))g_rsync=1;
            else if(!strcmp(a,"--test")){g_test=1;g_decomp=1;}
            else if(!strcmp(a,"--rle"))g_rle=1;
            else if(!strcmp(a,"--huffman"))g_huffman=1;
            else if(!strcmp(a,"--verbose"))g_verbose++;
            else if(!strcmp(a,"--version")){printf("pigz %s\n",PIGZ_VERSION);if(g_verbose)printf("zlib %s\n",zlibVersion());exit(0);}
            else if(!strcmp(a,"--zlib"))g_format=FMT_ZLIB;
            else if(!strcmp(a,"--synchronous"))g_sync=1;
            else if(!strcmp(a,"--first")){}
            else if(!strcmp(a,"--oneblock")){}
            else if(!strncmp(a,"--alias",7)){char*v=NULL;if(a[7]=='=')v=a+8;else get_arg_str(&p,&v,NULL);g_alias=v;}
            else if(!strncmp(a,"--comment",9)){char*v=NULL;if(a[9]=='=')v=a+10;else get_arg_str(&p,&v,NULL);g_comment=v;}
            else if(!strncmp(a,"--blocksize",11)){char*v=NULL;if(a[11]=='=')v=a+12;else get_arg_str(&p,&v,NULL);if(v)g_block=atoi(v)*1024;}
            else if(!strncmp(a,"--processes",11)){char*v=NULL;if(a[11]=='=')v=a+12;else get_arg_str(&p,&v,NULL);if(v)g_procs=atoi(v);}
            else if(!strncmp(a,"--suffix",8)){char*v=NULL;if(a[8]=='=')v=a+9;else get_arg_str(&p,&v,NULL);g_suffix=v;}
            else if(!strncmp(a,"--iterations",12)){char*v=NULL;if(a[12]=='=')v=a+13;else get_arg_str(&p,&v,NULL);}
            else if(!strncmp(a,"--maxsplits",11)){char*v=NULL;if(a[11]=='=')v=a+12;else get_arg_str(&p,&v,NULL);}
            else{if(!g_quiet)fprintf(stderr,"%s: invalid option: %s\n",prog,a);g_ret=1;}
            continue;
        }
        /* short options */
        for(int j=1;a[j];j++){
            char c=a[j];
            if(c>='0'&&c<='9'){
                if(c=='1'&&a[j+1]=='1'){g_level=11;j++;}
                else g_level=c-'0';
                continue;
            }
            char*rest=(a[j+1]?a+j+1:NULL);
            if(c=='A'){if(!rest&&p.i+1<argc){p.i++;rest=argv[p.i];}g_alias=rest;break;}
            if(c=='b'){if(!rest&&p.i+1<argc){p.i++;rest=argv[p.i];}if(rest)g_block=atoi(rest)*1024;break;}
            if(c=='c'){/* stdout mode, handled in main */continue;}
            if(c=='C'){if(!rest&&p.i+1<argc){p.i++;rest=argv[p.i];}g_comment=rest;break;}
            if(c=='d'){g_decomp=1;continue;}
            if(c=='f'){g_force=1;continue;}
            if(c=='F'){continue;}
            if(c=='h'){show_help();}
            if(c=='H'){g_huffman=1;continue;}
            if(c=='i'){g_indep=1;continue;}
            if(c=='I'){if(!rest&&p.i+1<argc)p.i++;break;}
            if(c=='J'){if(!rest&&p.i+1<argc)p.i++;break;}
            if(c=='k'){g_keep=1;continue;}
            if(c=='K'){g_format=FMT_ZIP;continue;}
            if(c=='l'){g_list=1;continue;}
            if(c=='L'){printf("pigz %s\nCopyright (C) 2007-2023 Mark Adler\nSubject to the terms of the zlib license.\nNo warranty is provided or implied.\n",PIGZ_VERSION);exit(0);}
            if(c=='m'){g_mtime=0;continue;}
            if(c=='M'){g_mtime=1;continue;}
            if(c=='n'){g_name=0;g_mtime=0;continue;}
            if(c=='N'){g_name=1;g_mtime=1;continue;}
            if(c=='O'){continue;}
            if(c=='p'){if(!rest&&p.i+1<argc){p.i++;rest=argv[p.i];}if(rest)g_procs=atoi(rest);break;}
            if(c=='q'){g_quiet=1;continue;}
            if(c=='r'){g_recur=1;continue;}
            if(c=='R'){g_rsync=1;continue;}
            if(c=='S'){if(!rest&&p.i+1<argc){p.i++;rest=argv[p.i];}g_suffix=rest;break;}
            if(c=='t'){g_test=1;g_decomp=1;continue;}
            if(c=='U'){g_rle=1;continue;}
            if(c=='v'){g_verbose++;continue;}
            if(c=='V'){printf("pigz %s\n",PIGZ_VERSION);if(g_verbose)printf("zlib %s\n",zlibVersion());exit(0);}
            if(c=='Y'){g_sync=1;continue;}
            if(c=='z'){g_format=FMT_ZLIB;continue;}
            if(!g_quiet)fprintf(stderr,"%s: invalid option: -%c\n",prog,c);
            g_ret=1;
        }
    }
    if(end)*end=p.i;
}

static void parse_env(const char*env){
    char*val=getenv(env);if(!val)return;
    char*copy=strdup(val);
    char*args[256];int n=1;args[0]=prog;
    char*tok=strtok(copy," \t\n");
    while(tok&&n<255){args[n++]=tok;tok=strtok(NULL," \t\n");}
    int end=1;parse_opts(n,args,1,&end);
    free(copy);
}

int main(int argc,char**argv){
    char*bn=strrchr(argv[0],'/');prog=bn?bn+1:argv[0];
    if(!strcmp(prog,"unpigz")){g_decomp=1;}

    parse_env("GZIP");
    parse_env("PIGZ");

    /* First pass: scan for -v before -V */
    for(int i=1;i<argc;i++){
        if(!strcmp(argv[i],"--"))break;
        if(argv[i][0]=='-'&&argv[i][1]!='-'){
